#[derive(Clone, Copy, Debug, Default, Serialize)]
pub struct PetLiteStageTiming {
    pub calls: usize,
    pub total_ms: f64,
}

impl PetLiteStageTiming {
    fn record(&mut self, start: Instant) {
        self.calls += 1;
        self.total_ms += elapsed_pet_ms(start);
    }

    fn record_elapsed_ms(&mut self, total_ms: f64) {
        self.calls += 1;
        self.total_ms += total_ms;
    }
}

