#[derive(Clone, Copy, Debug, Default, Serialize)]
pub struct PetLiteBufferAllocationCounter {
    pub calls: usize,
    pub reallocations: usize,
    pub last_len: usize,
    pub max_len: usize,
    pub last_capacity: usize,
    pub max_capacity: usize,
}

impl PetLiteBufferAllocationCounter {
    fn record(&mut self, stats: PetLiteBufferFillStats) {
        self.calls += 1;
        if stats.after_capacity > stats.before_capacity {
            self.reallocations += 1;
        }
        self.last_len = stats.len;
        self.last_capacity = stats.after_capacity;
        self.max_len = self.max_len.max(stats.len);
        self.max_capacity = self.max_capacity.max(stats.after_capacity);
    }
}

