    pub fn predict_for_batch_with_compute_dtype(
        &self,
        batch: &PetLiteBatch,
        cell: Option<&crate::Cell>,
        options: &PredictionOptions,
        dtype: PredictionComputeDtype,
    ) -> Result<Prediction, PetLiteError> {
        match dtype {
            PredictionComputeDtype::Float64 => self.predict_for_batch(batch, cell, options),
            PredictionComputeDtype::Float32 => self.predict_mad_s_f32_for_batch(batch, options),
        }
    }

    #[doc(hidden)]
    pub fn predict_for_batch_with_compute_dtype_and_f32_workspace(
        &self,
        batch: &PetLiteBatch,
        cell: Option<&crate::Cell>,
        options: &PredictionOptions,
        dtype: PredictionComputeDtype,
        workspace: &mut PetLitePreparedBatchF32Workspace,
    ) -> Result<Prediction, PetLiteError> {
        self.predict_for_batch_with_compute_dtype_and_f32_workspace_profiled(
            batch, cell, options, dtype, workspace, None,
        )
    }

    #[doc(hidden)]
    pub fn predict_for_batch_with_compute_dtype_and_f32_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        cell: Option<&crate::Cell>,
        options: &PredictionOptions,
        dtype: PredictionComputeDtype,
        workspace: &mut PetLitePreparedBatchF32Workspace,
        profile: Option<&mut PetLiteProfile>,
    ) -> Result<Prediction, PetLiteError> {
        match dtype {
            PredictionComputeDtype::Float64 => {
                self.predict_for_batch_profiled(batch, cell, options, profile)
            }
            PredictionComputeDtype::Float32 => self
                .predict_mad_s_f32_for_batch_with_workspace_profiled(
                    batch, options, workspace, profile,
                ),
        }
    }

    #[doc(hidden)]
    pub fn predict_for_batch_with_compute_dtype_and_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        cell: Option<&crate::Cell>,
        options: &PredictionOptions,
        dtype: PredictionComputeDtype,
        workspace: &mut PetLitePreparedBatchWorkspace,
        profile: Option<&mut PetLiteProfile>,
    ) -> Result<Prediction, PetLiteError> {
        match dtype {
            PredictionComputeDtype::Float64 => self
                .predict_for_batch_with_force_workspace_profiled(
                    batch,
                    cell,
                    options,
                    &mut workspace.force,
                    profile,
                ),
            PredictionComputeDtype::Float32 => self
                .predict_mad_s_f32_for_batch_with_workspace_profiled(
                    batch,
                    options,
                    &mut workspace.f32,
                    profile,
                ),
        }
    }

    fn predict_for_batch_with_force_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        cell: Option<&crate::Cell>,
        options: &PredictionOptions,
        workspace: &mut PetLiteForceWorkspace,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<Prediction, PetLiteError> {
        if !options.compute_energy
            && !options.compute_forces
            && !options.compute_stress
            && !options.compute_virial
        {
            return Ok(Prediction::default());
        }
        let _runtime_dims = self.supported_runtime_dims()?;
        let requests_stress_virial = options.compute_stress || options.compute_virial;
        let needs_vjp = options.compute_forces || options.compute_stress || options.compute_virial;
        let (energy, forces, stress, virial) = if needs_vjp {
            let (all_forces, displacement_gradient, per_system) = self
                .forces_displacement_gradient_and_energy_for_batch_with_workspace_profiled(
                    batch,
                    requests_stress_virial,
                    workspace,
                    profile.as_deref_mut(),
                )?;
            let energy = *per_system
                .first()
                .ok_or_else(|| invalid_model("PET post-processed energy output is empty"))?;
            let stress = if options.compute_stress {
                Some(stress_from_displacement_gradient(
                    displacement_gradient,
                    cell.ok_or(PetLiteError::UnsupportedRuntime)?,
                )?)
            } else {
                None
            };
            let virial = if options.compute_virial {
                Some(virial_from_displacement_gradient(displacement_gradient))
            } else {
                None
            };
            (
                energy,
                options.compute_forces.then_some(all_forces),
                stress,
                virial,
            )
        } else {
            let energy = self.energy_for_batch_profiled(batch, profile)?;
            (energy, None, None, None)
        };
        Ok(Prediction {
            energy: options.compute_energy.then_some(energy),
            forces,
            stress,
            virial,
        })
    }

    fn predict_mad_s_f32_for_batch(
        &self,
        batch: &PetLiteBatch,
        options: &PredictionOptions,
    ) -> Result<Prediction, PetLiteError> {
        let mut workspace = PetLitePreparedBatchF32Workspace::new();
        self.predict_mad_s_f32_for_batch_with_workspace(batch, options, &mut workspace)
    }

    fn predict_mad_s_f32_for_batch_with_workspace(
        &self,
        batch: &PetLiteBatch,
        options: &PredictionOptions,
        workspace: &mut PetLitePreparedBatchF32Workspace,
    ) -> Result<Prediction, PetLiteError> {
        self.predict_mad_s_f32_for_batch_with_workspace_profiled(batch, options, workspace, None)
    }

    fn predict_mad_s_f32_for_batch_with_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        options: &PredictionOptions,
        workspace: &mut PetLitePreparedBatchF32Workspace,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<Prediction, PetLiteError> {
        if !options.compute_energy
            && !options.compute_forces
            && !options.compute_stress
            && !options.compute_virial
        {
            return Ok(Prediction::default());
        }
        let runtime_dims = self.supported_runtime_dims()?;
        if !runtime_dims.is_supported_f32_runtime() || !self.has_native_f32_state_tensors() {
            return Err(PetLiteError::UnsupportedComputeDtype(
                PredictionComputeDtype::Float32,
            ));
        }
        let requests_stress_virial = options.compute_stress || options.compute_virial;
        if requests_stress_virial {
            return Err(PetLiteError::UnsupportedComputeDtype(
                PredictionComputeDtype::Float32,
            ));
        }
        if options.compute_forces && batch.n_atoms < 2 {
            return Err(PetLiteError::UnsupportedRuntime);
        }
        let needs_vjp = options.compute_forces;
        let (energy, forces, stress, virial) = if needs_vjp {
            let (all_forces, _, per_system) = self
                .forces_displacement_gradient_and_energy_for_batch_f32_with_workspace(
                    batch,
                    false,
                    workspace,
                    profile.as_deref_mut(),
                )?;
            let energy = *per_system
                .first()
                .ok_or_else(|| invalid_model("PET f32 post-processed energy output is empty"))?;
            (energy, Some(all_forces), None, None)
        } else {
            let energy =
                self.energy_for_batch_f32_with_workspace_profiled(batch, workspace, profile)?;
            (energy, None, None, None)
        };
        Ok(Prediction {
            energy: options.compute_energy.then_some(energy),
            forces,
            stress,
            virial,
        })
    }

    pub fn family(&self) -> &str {
        &self.source.family
    }

    pub fn size(&self) -> &str {
        &self.source.size
    }

    pub fn version(&self) -> &str {
        &self.source.version
    }

    pub fn checkpoint(&self) -> &str {
        &self.source.checkpoint
    }

    pub fn selected_model(&self) -> String {
        format!(
            "{}-{}-v{}",
            self.source.family, self.source.size, self.source.version
        )
    }

    pub fn type_names(&self) -> &[String] {
        &self.species.symbols
    }

    pub fn atomic_numbers(&self) -> &[usize] {
        &self.species.atomic_numbers
    }

    pub fn cutoff(&self) -> f64 {
        self.neighbor_selection.cutoff
    }

    pub fn max_neighbors(&self) -> usize {
        self.neighbor_selection.max_neighbors
    }

    pub fn upet_commit(&self) -> &str {
        &self.provenance.upet_commit
    }

    pub fn checkpoint_lfs_sha256(&self) -> &str {
        &self.provenance.checkpoint_lfs_sha256
    }

    pub fn energy_unit(&self) -> &str {
        &self.outputs.energy.unit
    }

    pub fn force_source(&self) -> &str {
        &self.outputs.forces.source
    }

