    fn runtime_dims_from_payload(&self) -> Result<PetLiteRuntimeDims, PetLiteError> {
        self.runtime_dims.ok_or(PetLiteError::UnsupportedRuntime)
    }

    fn derive_runtime_dims_from_payload(&self) -> Result<PetLiteRuntimeDims, PetLiteError> {
        let node_embedding = self.required_rank2_tensor(NODE_EMBEDDING_TENSOR)?;
        let edge_embedding = self.required_rank2_tensor(EDGE_EMBEDDING_TENSOR)?;
        let species_count = self.atomic_numbers().len();
        if node_embedding.shape[0] != species_count {
            return Err(invalid_model(format!(
                "PET node embedding tensor species axis must be {species_count}, got {}",
                node_embedding.shape[0]
            )));
        }
        if edge_embedding.shape[0] != species_count {
            return Err(invalid_model(format!(
                "PET edge embedding tensor species axis must be {species_count}, got {}",
                edge_embedding.shape[0]
            )));
        }
        let d_edge = self.edge_feature_dim();
        if edge_embedding.shape[1] != d_edge {
            return Err(invalid_model(format!(
                "PET edge embedding width must match architecture.edge_feature_dim {d_edge}, got {}",
                edge_embedding.shape[1]
            )));
        }
        let num_heads = self.architecture.num_heads.unwrap_or(PET_MAD_XS_NUM_HEADS);
        if num_heads == 0 {
            return Err(invalid_model("PET attention head count must be positive"));
        }
        if !d_edge.is_multiple_of(num_heads) {
            return Err(invalid_model(format!(
                "PET edge feature dim {d_edge} is not divisible by attention head count {num_heads}"
            )));
        }
        let d_node = node_embedding.shape[1];
        let attention_projection =
            self.rank2_shape("model.gnn_layers.0.trans.layers.0.attention.input_linear.weight")?;
        if attention_projection[1] != d_edge {
            return Err(invalid_model(format!(
                "PET attention input width must be {d_edge}, got {}",
                attention_projection[1]
            )));
        }
        if attention_projection[0] != 3 * d_edge {
            return Err(invalid_model(format!(
                "PET attention projection output width must be {}, got {}",
                3 * d_edge,
                attention_projection[0]
            )));
        }
        let attention_output =
            self.rank2_shape("model.gnn_layers.0.trans.layers.0.attention.output_linear.weight")?;
        if attention_output != [d_edge, d_edge] {
            return Err(invalid_model(format!(
                "PET attention output projection must be [{d_edge}, {d_edge}], got {attention_output:?}"
            )));
        }
        let token_mlp = self.rank2_shape("model.gnn_layers.0.trans.layers.0.mlp.w_in.weight")?;
        if token_mlp[1] != d_edge {
            return Err(invalid_model(format!(
                "PET token MLP input width must be {d_edge}, got {}",
                token_mlp[1]
            )));
        }
        if !token_mlp[0].is_multiple_of(2) {
            return Err(invalid_model(format!(
                "PET token MLP SwiGLU projection width must be even, got {}",
                token_mlp[0]
            )));
        }
        let token_mlp_projection = token_mlp[0];
        let token_mlp_hidden = token_mlp_projection / 2;
        let center_mlp =
            self.rank2_shape("model.gnn_layers.0.trans.layers.0.center_mlp.w_in.weight")?;
        if center_mlp[1] != d_node {
            return Err(invalid_model(format!(
                "PET center MLP input width must be {d_node}, got {}",
                center_mlp[1]
            )));
        }
        if !center_mlp[0].is_multiple_of(2) {
            return Err(invalid_model(format!(
                "PET center MLP SwiGLU projection width must be even, got {}",
                center_mlp[0]
            )));
        }
        let center_mlp_projection = center_mlp[0];
        let center_mlp_hidden = center_mlp_projection / 2;
        let node_head = self.rank2_shape("model.node_heads.energy.0.0.weight")?;
        if node_head[1] != d_node {
            return Err(invalid_model(format!(
                "PET node energy head input width must be {d_node}, got {}",
                node_head[1]
            )));
        }
        let edge_head = self.rank2_shape("model.edge_heads.energy.0.0.weight")?;
        if edge_head[1] != d_edge {
            return Err(invalid_model(format!(
                "PET edge energy head input width must be {d_edge}, got {}",
                edge_head[1]
            )));
        }
        if node_head[0] != edge_head[0] {
            return Err(invalid_model(format!(
                "PET node/edge energy head hidden widths must match, got {} and {}",
                node_head[0], edge_head[0]
            )));
        }
        let energy_head_hidden = node_head[0];
        self.expect_rank1_len("model.node_heads.energy.0.0.bias", energy_head_hidden)?;
        self.expect_rank2_shape(
            "model.node_heads.energy.0.2.weight",
            [d_edge, energy_head_hidden],
        )?;
        self.expect_rank1_len("model.node_heads.energy.0.2.bias", d_edge)?;
        self.expect_rank1_len("model.edge_heads.energy.0.0.bias", energy_head_hidden)?;
        self.expect_rank2_shape(
            "model.edge_heads.energy.0.2.weight",
            [d_edge, energy_head_hidden],
        )?;
        self.expect_rank1_len("model.edge_heads.energy.0.2.bias", d_edge)?;
        self.expect_rank2_shape(
            "model.node_last_layers.energy.0.energy___0.weight",
            [1, d_edge],
        )?;
        self.expect_rank1_len("model.node_last_layers.energy.0.energy___0.bias", 1)?;
        self.expect_rank2_shape(
            "model.edge_last_layers.energy.0.energy___0.weight",
            [1, d_edge],
        )?;
        self.expect_rank1_len("model.edge_last_layers.energy.0.energy___0.bias", 1)?;
        if self.attention_layers() == 0 {
            return Err(invalid_model(
                "PET architecture attention_layers must be positive",
            ));
        }
        for layer in 0..self.gnn_layers() {
            let merge_parts = if layer == 0 { 2 } else { 3 };
            let pair_edge_dim = 2 * d_edge;
            self.expect_rank1_len(
                &format!("model.combination_norms.{layer}.weight"),
                pair_edge_dim,
            )?;
            self.expect_rank1_len(
                &format!("model.combination_norms.{layer}.bias"),
                pair_edge_dim,
            )?;
            self.expect_rank2_shape(
                &format!("model.combination_mlps.{layer}.0.weight"),
                [pair_edge_dim, pair_edge_dim],
            )?;
            self.expect_rank1_len(
                &format!("model.combination_mlps.{layer}.0.bias"),
                pair_edge_dim,
            )?;
            self.expect_rank2_shape(
                &format!("model.combination_mlps.{layer}.2.weight"),
                [d_edge, pair_edge_dim],
            )?;
            self.expect_rank1_len(&format!("model.combination_mlps.{layer}.2.bias"), d_edge)?;
            for attention_layer in 0..self.attention_layers() {
                let trans_prefix =
                    format!("model.gnn_layers.{layer}.trans.layers.{attention_layer}");
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.attention.input_linear.weight"),
                    [3 * d_edge, d_edge],
                )?;
                self.expect_rank1_len(
                    &format!("{trans_prefix}.attention.input_linear.bias"),
                    3 * d_edge,
                )?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.attention.output_linear.weight"),
                    [d_edge, d_edge],
                )?;
                self.expect_rank1_len(
                    &format!("{trans_prefix}.attention.output_linear.bias"),
                    d_edge,
                )?;
                self.expect_rank1_len(&format!("{trans_prefix}.norm_attention.weight"), d_edge)?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.center_contraction.weight"),
                    [d_edge, d_node],
                )?;
                self.expect_rank1_len(&format!("{trans_prefix}.center_contraction.bias"), d_edge)?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.center_expansion.weight"),
                    [d_node, d_edge],
                )?;
                self.expect_rank1_len(&format!("{trans_prefix}.center_expansion.bias"), d_node)?;
                self.expect_rank1_len(
                    &format!("{trans_prefix}.norm_center_features.weight"),
                    d_node,
                )?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.mlp.w_in.weight"),
                    [token_mlp_projection, d_edge],
                )?;
                self.expect_rank1_len(
                    &format!("{trans_prefix}.mlp.w_in.bias"),
                    token_mlp_projection,
                )?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.mlp.w_out.weight"),
                    [d_edge, token_mlp_hidden],
                )?;
                self.expect_rank1_len(&format!("{trans_prefix}.mlp.w_out.bias"), d_edge)?;
                self.expect_rank1_len(&format!("{trans_prefix}.norm_mlp.weight"), d_edge)?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.center_mlp.w_in.weight"),
                    [center_mlp_projection, d_node],
                )?;
                self.expect_rank1_len(
                    &format!("{trans_prefix}.center_mlp.w_in.bias"),
                    center_mlp_projection,
                )?;
                self.expect_rank2_shape(
                    &format!("{trans_prefix}.center_mlp.w_out.weight"),
                    [d_node, center_mlp_hidden],
                )?;
                self.expect_rank1_len(&format!("{trans_prefix}.center_mlp.w_out.bias"), d_node)?;
            }
            self.expect_rank2_shape(
                &format!("model.gnn_layers.{layer}.edge_embedder.weight"),
                [d_edge, 4],
            )?;
            self.expect_rank1_len(
                &format!("model.gnn_layers.{layer}.edge_embedder.bias"),
                d_edge,
            )?;
            self.expect_rank2_shape(
                &format!("model.gnn_layers.{layer}.compress.0.weight"),
                [d_edge, merge_parts * d_edge],
            )?;
            self.expect_rank1_len(&format!("model.gnn_layers.{layer}.compress.0.bias"), d_edge)?;
            self.expect_rank2_shape(
                &format!("model.gnn_layers.{layer}.compress.2.weight"),
                [d_edge, d_edge],
            )?;
            self.expect_rank1_len(&format!("model.gnn_layers.{layer}.compress.2.bias"), d_edge)?;
            if layer > 0 {
                self.expect_rank2_shape(
                    &format!("model.gnn_layers.{layer}.neighbor_embedder.weight"),
                    [species_count, d_edge],
                )?;
            }
        }
        Ok(PetLiteRuntimeDims {
            d_node,
            d_edge,
            attention_projection_dim: attention_projection[0],
            token_mlp_hidden: token_mlp_projection,
            center_mlp_hidden: center_mlp_projection,
            energy_head_hidden,
            gnn_layers: self.gnn_layers(),
            attention_layers: self.attention_layers(),
            max_neighbors: self.max_neighbors(),
            num_heads,
            head_dim: d_edge / num_heads,
            cutoff_width: PET_MAD_XS_CUTOFF_WIDTH,
        })
    }

    fn supported_runtime_dims(&self) -> Result<PetLiteRuntimeDims, PetLiteError> {
        let dims = self.runtime_dims_from_payload()?;
        if dims.is_supported_runtime() {
            Ok(dims)
        } else {
            Err(PetLiteError::UnsupportedRuntime)
        }
    }

