    fn input_edge_embeddings_into(
        &self,
        element_indices_neighbors: &[Vec<usize>],
        output: &mut Vec<f64>,
    ) -> Result<PetLiteBufferFillStats, PetLiteError> {
        let tensor = self.required_rank2_tensor(EDGE_EMBEDDING_TENSOR)?;
        let row_width = tensor.shape[1];
        let max_edges = element_indices_neighbors
            .first()
            .map_or(0, std::vec::Vec::len);
        let expected_len = element_indices_neighbors
            .len()
            .checked_mul(max_edges)
            .and_then(|value| value.checked_mul(row_width))
            .ok_or_else(|| invalid_model("PET edge embedding output size overflows"))?;
        let before_capacity = output.capacity();
        output.clear();
        output.reserve(expected_len);
        for (atom, row) in element_indices_neighbors.iter().enumerate() {
            if row.len() != max_edges {
                return Err(invalid_model(format!(
                    "element_indices_neighbors must be rectangular; row 0 has length {max_edges}, row {atom} has length {}",
                    row.len()
                )));
            }
            for &element_index in row {
                append_tensor_row_checked(EDGE_EMBEDDING_TENSOR, tensor, element_index, output)?;
            }
        }
        Ok(PetLiteBufferFillStats {
            len: output.len(),
            before_capacity,
            after_capacity: output.capacity(),
        })
    }

