    pub fn reverse_edge_embeddings(
        edge_embeddings: &[f64],
        n_atoms: usize,
        max_edges_per_atom: usize,
        edge_dim: usize,
        reverse_neighbor_index: &[Vec<usize>],
    ) -> Result<Vec<f64>, PetLiteError> {
        if edge_dim == 0 {
            return Err(invalid_model(
                "PET edge embedding dimension must be nonzero",
            ));
        }
        if reverse_neighbor_index.len() != n_atoms {
            return Err(invalid_model(format!(
                "reverse_neighbor_index row count {} does not match n_atoms {n_atoms}",
                reverse_neighbor_index.len()
            )));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET reverse-edge slot count overflows"))?;
        let expected_len = edge_slots
            .checked_mul(edge_dim)
            .ok_or_else(|| invalid_model("PET reverse-edge embedding length overflows"))?;
        if edge_embeddings.len() != expected_len {
            return Err(invalid_model(format!(
                "PET edge embeddings length must be {expected_len} for shape [{n_atoms}, {max_edges_per_atom}, {edge_dim}], got {}",
                edge_embeddings.len()
            )));
        }
        let mut reversed = Vec::with_capacity(expected_len);
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            if row.len() != max_edges_per_atom {
                return Err(invalid_model(format!(
                    "reverse_neighbor_index must be rectangular; expected row length {max_edges_per_atom}, row {atom} has length {}",
                    row.len()
                )));
            }
            for (edge, &source_slot) in row.iter().enumerate() {
                if source_slot >= edge_slots {
                    return Err(invalid_model(format!(
                        "reverse_neighbor_index[{atom}][{edge}]={source_slot} is out of bounds for {edge_slots} flattened edge slots"
                    )));
                }
                let start = source_slot
                    .checked_mul(edge_dim)
                    .ok_or_else(|| invalid_model("PET reverse-edge source offset overflows"))?;
                let end = start
                    .checked_add(edge_dim)
                    .ok_or_else(|| invalid_model("PET reverse-edge source end overflows"))?;
                reversed.extend_from_slice(&edge_embeddings[start..end]);
            }
        }
        Ok(reversed)
    }

