    pub fn reverse_edge_embeddings_vjp(
        bar_reversed_edge_embeddings: &[f64],
        n_atoms: usize,
        max_edges_per_atom: usize,
        edge_dim: usize,
        reverse_neighbor_index: &[Vec<usize>],
    ) -> Result<Vec<f64>, PetLiteError> {
        if edge_dim == 0 {
            return Err(invalid_model(
                "PET reverse-edge VJP embedding dimension must be nonzero",
            ));
        }
        if reverse_neighbor_index.len() != n_atoms {
            return Err(invalid_model(format!(
                "reverse_neighbor_index row count {} does not match n_atoms {n_atoms}",
                reverse_neighbor_index.len()
            )));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET reverse-edge VJP slot count overflows"))?;
        let expected_len = edge_slots
            .checked_mul(edge_dim)
            .ok_or_else(|| invalid_model("PET reverse-edge VJP embedding length overflows"))?;
        expect_shape_len(
            "reverse-edge VJP bar_reversed_edge_embeddings",
            bar_reversed_edge_embeddings,
            edge_slots,
            edge_dim,
        )?;
        let mut bar_edge_embeddings = vec![0.0; expected_len];
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            if row.len() != max_edges_per_atom {
                return Err(invalid_model(format!(
                    "reverse_neighbor_index must be rectangular; expected row length {max_edges_per_atom}, row {atom} has length {}",
                    row.len()
                )));
            }
            for (edge, &source_slot) in row.iter().enumerate() {
                if source_slot >= edge_slots {
                    return Err(invalid_model(format!(
                        "reverse_neighbor_index[{atom}][{edge}]={source_slot} is out of bounds for {edge_slots} flattened edge slots"
                    )));
                }
                let reversed_start = (atom * max_edges_per_atom + edge)
                    .checked_mul(edge_dim)
                    .ok_or_else(|| invalid_model("PET reverse-edge VJP output offset overflows"))?;
                let source_start = source_slot
                    .checked_mul(edge_dim)
                    .ok_or_else(|| invalid_model("PET reverse-edge VJP source offset overflows"))?;
                for component in 0..edge_dim {
                    bar_edge_embeddings[source_start + component] +=
                        bar_reversed_edge_embeddings[reversed_start + component];
                }
            }
        }
        Ok(bar_edge_embeddings)
    }

