    pub fn gnn_edge_combination(
        &self,
        layer: usize,
        input_edge_embeddings: &[f64],
        output_edge_embeddings: &[f64],
        reverse_neighbor_index: &[Vec<usize>],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<(Vec<f64>, Vec<f64>), PetLiteError> {
        let (combination_update, next_edge_embeddings, _) = self.gnn_edge_combination_cached(
            layer,
            input_edge_embeddings,
            output_edge_embeddings,
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            None,
            None,
            true,
        )?;
        Ok((combination_update, next_edge_embeddings))
    }

    #[doc(hidden)]
    #[allow(clippy::too_many_arguments, dead_code)]
    pub fn gnn_edge_combination_f32(
        &self,
        layer: usize,
        input_edge_embeddings: &[f32],
        output_edge_embeddings: &[f32],
        reverse_neighbor_index: &[Vec<usize>],
        n_atoms: usize,
        max_edges_per_atom: usize,
        padding_mask: Option<&[bool]>,
    ) -> Result<(Vec<f32>, Vec<f32>), PetLiteError> {
        let (combination_update, next_edge_embeddings, _) = self.gnn_edge_combination_cached_f32(
            layer,
            input_edge_embeddings,
            output_edge_embeddings,
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            padding_mask,
            None,
            true,
        )?;
        Ok((combination_update, next_edge_embeddings))
    }

    #[allow(clippy::too_many_arguments, clippy::type_complexity, dead_code)]
    fn gnn_edge_combination_cached_f32(
        &self,
        layer: usize,
        input_edge_embeddings: &[f32],
        output_edge_embeddings: &[f32],
        reverse_neighbor_index: &[Vec<usize>],
        n_atoms: usize,
        max_edges_per_atom: usize,
        padding_mask: Option<&[bool]>,
        precomputed_active_rows: Option<&PetLiteActiveEdgeMetadata>,
        materialize_update: bool,
    ) -> Result<(Vec<f32>, Vec<f32>, PetLiteEdgeCombinationForwardCacheF32), PetLiteError> {
        if layer >= self.gnn_layers() {
            return Err(invalid_model(format!(
                "PET f32 edge combination layer {layer} is out of bounds for {} GNN layers",
                self.gnn_layers()
            )));
        }
        if n_atoms == 0 {
            return Err(invalid_model(
                "PET f32 edge combination atom count must be nonzero",
            ));
        }
        if max_edges_per_atom == 0 {
            return Err(invalid_model(
                "PET f32 edge combination max edges per atom must be nonzero",
            ));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 edge combination slot count overflows"))?;
        let dims = self.runtime_dims_from_payload()?;
        let d_edge = dims.d_edge;
        let pair_edge_dim = 2 * d_edge;
        expect_shape_len_f32(
            "f32 input_edge_embeddings",
            input_edge_embeddings,
            edge_slots,
            d_edge,
        )?;
        expect_shape_len_f32(
            "f32 output_edge_embeddings",
            output_edge_embeddings,
            edge_slots,
            d_edge,
        )?;
        validate_rectangular_usize_matrix(
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            "reverse_neighbor_index",
        )?;
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            for (edge, &source_slot) in row.iter().enumerate() {
                if source_slot >= edge_slots {
                    return Err(invalid_model(format!(
                        "reverse_neighbor_index[{atom}][{edge}]={source_slot} is out of bounds for {edge_slots} flattened edge slots"
                    )));
                }
            }
        }
        let (active_rows, active_row_lookup) = if let Some(mask) = padding_mask {
            if mask.len() != edge_slots {
                return Err(invalid_model(format!(
                    "PET f32 edge combination padding_mask length must be {edge_slots}, got {}",
                    mask.len()
                )));
            }
            if dims.uses_active_edge_compaction_for(edge_slots) {
                if let Some(metadata) = precomputed_active_rows {
                    (
                        metadata.rows().map(Arc::clone),
                        metadata.row_lookup().map(Arc::clone),
                    )
                } else if let Some(rows) = active_edge_combination_row_indices(
                    edge_slots,
                    mask,
                    reverse_neighbor_index,
                    max_edges_per_atom,
                ) {
                    let row_lookup = active_edge_row_lookup(edge_slots, &rows);
                    (Some(Arc::<[usize]>::from(rows)), Some(row_lookup))
                } else {
                    (None, None)
                }
            } else {
                (None, None)
            }
        } else {
            (None, None)
        };

        let norm_weight = self.float_tensor_f32(
            &format!("model.combination_norms.{layer}.weight"),
            &[pair_edge_dim],
        )?;
        let norm_bias = self.float_tensor_f32(
            &format!("model.combination_norms.{layer}.bias"),
            &[pair_edge_dim],
        )?;
        let first_weight = self.float_tensor_f32(
            &format!("model.combination_mlps.{layer}.0.weight"),
            &[pair_edge_dim, pair_edge_dim],
        )?;
        let first_bias = self.float_tensor_f32(
            &format!("model.combination_mlps.{layer}.0.bias"),
            &[pair_edge_dim],
        )?;
        let second_weight = self.float_tensor_f32(
            &format!("model.combination_mlps.{layer}.2.weight"),
            &[d_edge, pair_edge_dim],
        )?;
        let second_bias =
            self.float_tensor_f32(&format!("model.combination_mlps.{layer}.2.bias"), &[d_edge])?;

        if let Some(active_rows) = active_rows {
            let active_rows_slice = active_rows.as_ref();
            let mut compact_pre_norm = vec![0.0; active_rows_slice.len() * pair_edge_dim];
            #[cfg(feature = "parallel")]
            if should_parallel_row_values(active_rows_slice.len(), pair_edge_dim) {
                compact_pre_norm
                    .par_chunks_mut(pair_edge_dim)
                    .zip(active_rows_slice.par_iter())
                    .for_each(|(pre_norm_row, &edge_slot)| {
                        let atom = edge_slot / max_edges_per_atom;
                        let edge = edge_slot % max_edges_per_atom;
                        let source_slot = reverse_neighbor_index[atom][edge];
                        let output_start = edge_slot * d_edge;
                        let source_start = source_slot * d_edge;
                        pre_norm_row[..d_edge].copy_from_slice(
                            &output_edge_embeddings[output_start..output_start + d_edge],
                        );
                        pre_norm_row[d_edge..pair_edge_dim].copy_from_slice(
                            &output_edge_embeddings[source_start..source_start + d_edge],
                        );
                    });
            }
            #[cfg(not(feature = "parallel"))]
            {
                for (compact_row, &edge_slot) in active_rows_slice.iter().enumerate() {
                    let atom = edge_slot / max_edges_per_atom;
                    let edge = edge_slot % max_edges_per_atom;
                    let source_slot = reverse_neighbor_index[atom][edge];
                    let output_start = edge_slot * d_edge;
                    let source_start = source_slot * d_edge;
                    let pre_norm_start = compact_row * pair_edge_dim;
                    let reversed_start = pre_norm_start + d_edge;
                    compact_pre_norm[pre_norm_start..reversed_start].copy_from_slice(
                        &output_edge_embeddings[output_start..output_start + d_edge],
                    );
                    compact_pre_norm[reversed_start..reversed_start + d_edge].copy_from_slice(
                        &output_edge_embeddings[source_start..source_start + d_edge],
                    );
                }
            }
            #[cfg(feature = "parallel")]
            if !should_parallel_row_values(active_rows_slice.len(), pair_edge_dim) {
                for (compact_row, &edge_slot) in active_rows_slice.iter().enumerate() {
                    let atom = edge_slot / max_edges_per_atom;
                    let edge = edge_slot % max_edges_per_atom;
                    let source_slot = reverse_neighbor_index[atom][edge];
                    let output_start = edge_slot * d_edge;
                    let source_start = source_slot * d_edge;
                    let pre_norm_start = compact_row * pair_edge_dim;
                    let reversed_start = pre_norm_start + d_edge;
                    compact_pre_norm[pre_norm_start..reversed_start].copy_from_slice(
                        &output_edge_embeddings[output_start..output_start + d_edge],
                    );
                    compact_pre_norm[reversed_start..reversed_start + d_edge].copy_from_slice(
                        &output_edge_embeddings[source_start..source_start + d_edge],
                    );
                }
            }
            let mut compact_normalized = compact_pre_norm.clone();
            let (compact_pre_norm_mean, compact_pre_norm_inv_std) =
                layer_norm_rows_cached_stats_f32(
                    &mut compact_normalized,
                    active_rows_slice.len(),
                    pair_edge_dim,
                    norm_weight,
                    norm_bias,
                    PET_MAD_XS_LAYER_NORM_EPS as f32,
                )?;
            let mut compact_first_preactivation = dense_forward_f32(
                &compact_normalized,
                active_rows_slice.len(),
                pair_edge_dim,
                first_weight,
                first_bias,
            )?;
            let compact_first_activation_sigmoid =
                apply_silu_cached_sigmoid_f32(&mut compact_first_preactivation);
            let compact_combination_update = dense_forward_f32(
                &compact_first_preactivation,
                active_rows_slice.len(),
                pair_edge_dim,
                second_weight,
                second_bias,
            )?;
            let combination_update = if materialize_update {
                scatter_selected_rows_to_padded_f32(
                    &compact_combination_update,
                    edge_slots,
                    d_edge,
                    active_rows_slice,
                    "PET f32 active edge combination update",
                )?
            } else {
                Vec::new()
            };
            let mut next_edge_embeddings =
                add_equal_len_f32(input_edge_embeddings, output_edge_embeddings)?;
            scatter_add_selected_rows_f32(
                &mut next_edge_embeddings,
                edge_slots,
                d_edge,
                active_rows_slice,
                &compact_combination_update,
                "PET f32 active edge combination next embeddings",
            )?;
            return Ok((
                combination_update,
                next_edge_embeddings,
                PetLiteEdgeCombinationForwardCacheF32 {
                    pre_norm: compact_pre_norm,
                    pre_norm_mean: compact_pre_norm_mean,
                    pre_norm_inv_std: compact_pre_norm_inv_std,
                    first_activation: compact_first_preactivation,
                    first_activation_sigmoid: compact_first_activation_sigmoid,
                    active_rows: Some(active_rows),
                    active_row_lookup,
                },
            ));
        }

        let mut pre_norm = vec![0.0; edge_slots * pair_edge_dim];
        #[cfg(feature = "parallel")]
        if should_parallel_row_values(edge_slots, pair_edge_dim) {
            pre_norm.par_chunks_mut(pair_edge_dim).enumerate().for_each(
                |(edge_slot, pre_norm_row)| {
                    let atom = edge_slot / max_edges_per_atom;
                    let edge = edge_slot % max_edges_per_atom;
                    let source_slot = reverse_neighbor_index[atom][edge];
                    let output_start = edge_slot * d_edge;
                    let source_start = source_slot * d_edge;
                    pre_norm_row[..d_edge].copy_from_slice(
                        &output_edge_embeddings[output_start..output_start + d_edge],
                    );
                    pre_norm_row[d_edge..pair_edge_dim].copy_from_slice(
                        &output_edge_embeddings[source_start..source_start + d_edge],
                    );
                },
            );
        }
        #[cfg(not(feature = "parallel"))]
        {
            for (atom, row) in reverse_neighbor_index.iter().enumerate() {
                for (edge, &source_slot) in row.iter().enumerate() {
                    let edge_slot = atom * max_edges_per_atom + edge;
                    let output_start = edge_slot * d_edge;
                    let source_start = source_slot * d_edge;
                    let pre_norm_start = edge_slot * pair_edge_dim;
                    let reversed_start = pre_norm_start + d_edge;
                    pre_norm[pre_norm_start..reversed_start].copy_from_slice(
                        &output_edge_embeddings[output_start..output_start + d_edge],
                    );
                    pre_norm[reversed_start..reversed_start + d_edge].copy_from_slice(
                        &output_edge_embeddings[source_start..source_start + d_edge],
                    );
                }
            }
        }
        #[cfg(feature = "parallel")]
        if !should_parallel_row_values(edge_slots, pair_edge_dim) {
            for (atom, row) in reverse_neighbor_index.iter().enumerate() {
                for (edge, &source_slot) in row.iter().enumerate() {
                    let edge_slot = atom * max_edges_per_atom + edge;
                    let output_start = edge_slot * d_edge;
                    let source_start = source_slot * d_edge;
                    let pre_norm_start = edge_slot * pair_edge_dim;
                    let reversed_start = pre_norm_start + d_edge;
                    pre_norm[pre_norm_start..reversed_start].copy_from_slice(
                        &output_edge_embeddings[output_start..output_start + d_edge],
                    );
                    pre_norm[reversed_start..reversed_start + d_edge].copy_from_slice(
                        &output_edge_embeddings[source_start..source_start + d_edge],
                    );
                }
            }
        }
        let mut normalized = pre_norm.clone();
        let (pre_norm_mean, pre_norm_inv_std) = layer_norm_rows_cached_stats_f32(
            &mut normalized,
            edge_slots,
            pair_edge_dim,
            norm_weight,
            norm_bias,
            PET_MAD_XS_LAYER_NORM_EPS as f32,
        )?;
        let mut first_preactivation = dense_forward_f32(
            &normalized,
            edge_slots,
            pair_edge_dim,
            first_weight,
            first_bias,
        )?;
        let first_activation_sigmoid = apply_silu_cached_sigmoid_f32(&mut first_preactivation);
        let combination_update = dense_forward_f32(
            &first_preactivation,
            edge_slots,
            pair_edge_dim,
            second_weight,
            second_bias,
        )?;
        let next_edge_embeddings = add_three_equal_len_f32(
            input_edge_embeddings,
            output_edge_embeddings,
            &combination_update,
        )?;
        Ok((
            combination_update,
            next_edge_embeddings,
            PetLiteEdgeCombinationForwardCacheF32 {
                pre_norm,
                pre_norm_mean,
                pre_norm_inv_std,
                first_activation: first_preactivation,
                first_activation_sigmoid,
                active_rows: None,
                active_row_lookup: None,
            },
        ))
    }

    #[allow(clippy::too_many_arguments, clippy::type_complexity)]
    fn gnn_edge_combination_cached(
        &self,
        layer: usize,
        input_edge_embeddings: &[f64],
        output_edge_embeddings: &[f64],
        reverse_neighbor_index: &[Vec<usize>],
        n_atoms: usize,
        max_edges_per_atom: usize,
        padding_mask: Option<&[bool]>,
        precomputed_active_rows: Option<&PetLiteActiveEdgeMetadata>,
        materialize_update: bool,
    ) -> Result<(Vec<f64>, Vec<f64>, PetLiteEdgeCombinationForwardCache), PetLiteError> {
        if layer >= self.gnn_layers() {
            return Err(invalid_model(format!(
                "PET edge combination layer {layer} is out of bounds for {} GNN layers",
                self.gnn_layers()
            )));
        }
        if n_atoms == 0 {
            return Err(invalid_model(
                "PET edge combination atom count must be nonzero",
            ));
        }
        if max_edges_per_atom == 0 {
            return Err(invalid_model(
                "PET edge combination max edges per atom must be nonzero",
            ));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET edge combination slot count overflows"))?;
        let dims = self.runtime_dims_from_payload()?;
        let d_edge = dims.d_edge;
        let pair_edge_dim = 2 * d_edge;
        expect_shape_len(
            "input_edge_embeddings",
            input_edge_embeddings,
            edge_slots,
            d_edge,
        )?;
        expect_shape_len(
            "output_edge_embeddings",
            output_edge_embeddings,
            edge_slots,
            d_edge,
        )?;
        validate_rectangular_usize_matrix(
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            "reverse_neighbor_index",
        )?;
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            for (edge, &source_slot) in row.iter().enumerate() {
                if source_slot >= edge_slots {
                    return Err(invalid_model(format!(
                        "reverse_neighbor_index[{atom}][{edge}]={source_slot} is out of bounds for {edge_slots} flattened edge slots"
                    )));
                }
            }
        }
        let active_rows = if let Some(mask) = padding_mask {
            if mask.len() != edge_slots {
                return Err(invalid_model(format!(
                    "PET edge combination padding_mask length must be {edge_slots}, got {}",
                    mask.len()
                )));
            }
            if dims.uses_active_edge_compaction_for(edge_slots) {
                if let Some(metadata) = precomputed_active_rows {
                    metadata.rows().map(Arc::clone)
                } else {
                    active_edge_combination_row_indices(
                        edge_slots,
                        mask,
                        reverse_neighbor_index,
                        max_edges_per_atom,
                    )
                    .map(Arc::<[usize]>::from)
                }
            } else {
                None
            }
        } else {
            None
        };
        let norm_weight = self.float_tensor(
            &format!("model.combination_norms.{layer}.weight"),
            &[pair_edge_dim],
        )?;
        let norm_bias = self.float_tensor(
            &format!("model.combination_norms.{layer}.bias"),
            &[pair_edge_dim],
        )?;
        let first_weight = self.float_tensor(
            &format!("model.combination_mlps.{layer}.0.weight"),
            &[pair_edge_dim, pair_edge_dim],
        )?;
        let first_bias = self.float_tensor(
            &format!("model.combination_mlps.{layer}.0.bias"),
            &[pair_edge_dim],
        )?;
        let second_weight = self.float_tensor(
            &format!("model.combination_mlps.{layer}.2.weight"),
            &[d_edge, pair_edge_dim],
        )?;
        let second_bias =
            self.float_tensor(&format!("model.combination_mlps.{layer}.2.bias"), &[d_edge])?;

        if let Some(active_rows) = active_rows {
            let active_rows_slice = active_rows.as_ref();
            let mut compact_pre_norm = vec![0.0; active_rows_slice.len() * pair_edge_dim];
            for (compact_row, &edge_slot) in active_rows_slice.iter().enumerate() {
                let atom = edge_slot / max_edges_per_atom;
                let edge = edge_slot % max_edges_per_atom;
                let source_slot = reverse_neighbor_index[atom][edge];
                let output_start = edge_slot * d_edge;
                let source_start = source_slot * d_edge;
                let pre_norm_start = compact_row * pair_edge_dim;
                let reversed_start = pre_norm_start + d_edge;
                compact_pre_norm[pre_norm_start..reversed_start]
                    .copy_from_slice(&output_edge_embeddings[output_start..output_start + d_edge]);
                compact_pre_norm[reversed_start..reversed_start + d_edge]
                    .copy_from_slice(&output_edge_embeddings[source_start..source_start + d_edge]);
            }
            let mut compact_normalized = compact_pre_norm.clone();
            let (compact_pre_norm_mean, compact_pre_norm_inv_std) = layer_norm_rows_cached_stats(
                &mut compact_normalized,
                active_rows_slice.len(),
                pair_edge_dim,
                norm_weight,
                norm_bias,
                PET_MAD_XS_LAYER_NORM_EPS,
            )?;
            let compact_first_preactivation = dense_forward(
                &compact_normalized,
                active_rows_slice.len(),
                pair_edge_dim,
                first_weight,
                first_bias,
            )?;
            let mut compact_hidden = compact_first_preactivation.clone();
            let compact_first_activation_sigmoid = apply_silu_cached_sigmoid(&mut compact_hidden);
            let compact_combination_update = dense_forward(
                &compact_hidden,
                active_rows_slice.len(),
                pair_edge_dim,
                second_weight,
                second_bias,
            )?;
            let combination_update = if materialize_update {
                scatter_selected_rows_to_padded(
                    &compact_combination_update,
                    edge_slots,
                    d_edge,
                    active_rows_slice,
                    "PET active edge combination update",
                )?
            } else {
                Vec::new()
            };
            let mut next_edge_embeddings =
                add_equal_len(input_edge_embeddings, output_edge_embeddings)?;
            scatter_add_selected_rows(
                &mut next_edge_embeddings,
                edge_slots,
                d_edge,
                active_rows_slice,
                &compact_combination_update,
                "PET active edge combination next embeddings",
            )?;
            return Ok((
                combination_update,
                next_edge_embeddings,
                PetLiteEdgeCombinationForwardCache {
                    pre_norm: compact_pre_norm,
                    pre_norm_mean: compact_pre_norm_mean,
                    pre_norm_inv_std: compact_pre_norm_inv_std,
                    first_preactivation: compact_first_preactivation,
                    first_activation_sigmoid: compact_first_activation_sigmoid,
                    active_rows: Some(active_rows),
                },
            ));
        }

        let mut pre_norm = vec![0.0; edge_slots * pair_edge_dim];
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            for (edge, &source_slot) in row.iter().enumerate() {
                let edge_slot = atom * max_edges_per_atom + edge;
                let output_start = edge_slot * d_edge;
                let source_start = source_slot * d_edge;
                let pre_norm_start = edge_slot * pair_edge_dim;
                let reversed_start = pre_norm_start + d_edge;
                pre_norm[pre_norm_start..reversed_start]
                    .copy_from_slice(&output_edge_embeddings[output_start..output_start + d_edge]);
                pre_norm[reversed_start..reversed_start + d_edge]
                    .copy_from_slice(&output_edge_embeddings[source_start..source_start + d_edge]);
            }
        }
        let mut normalized = pre_norm.clone();
        let (pre_norm_mean, pre_norm_inv_std) = layer_norm_rows_cached_stats(
            &mut normalized,
            edge_slots,
            pair_edge_dim,
            norm_weight,
            norm_bias,
            PET_MAD_XS_LAYER_NORM_EPS,
        )?;

        let first_preactivation = dense_forward(
            &normalized,
            edge_slots,
            pair_edge_dim,
            first_weight,
            first_bias,
        )?;
        let mut hidden = first_preactivation.clone();
        let first_activation_sigmoid = apply_silu_cached_sigmoid(&mut hidden);
        let combination_update = dense_forward(
            &hidden,
            edge_slots,
            pair_edge_dim,
            second_weight,
            second_bias,
        )?;
        let mut next_edge_embeddings =
            add_equal_len(input_edge_embeddings, output_edge_embeddings)?;
        add_assign_equal_len(&mut next_edge_embeddings, &combination_update)?;
        Ok((
            combination_update,
            next_edge_embeddings,
            PetLiteEdgeCombinationForwardCache {
                pre_norm,
                pre_norm_mean,
                pre_norm_inv_std,
                first_preactivation,
                first_activation_sigmoid,
                active_rows: None,
            },
        ))
    }

    #[allow(clippy::too_many_arguments)]
    pub fn gnn_edge_combination_vjp(
        &self,
        layer: usize,
        output_edge_embeddings: &[f64],
        reverse_neighbor_index: &[Vec<usize>],
        bar_combination_update: &[f64],
        bar_next_edge_embeddings: &[f64],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<PetLiteEdgeCombinationVjp, PetLiteError> {
        if layer >= self.gnn_layers() {
            return Err(invalid_model(format!(
                "PET edge combination VJP layer {layer} is out of bounds for {} GNN layers",
                self.gnn_layers()
            )));
        }
        if n_atoms == 0 {
            return Err(invalid_model(
                "PET edge combination VJP atom count must be nonzero",
            ));
        }
        if max_edges_per_atom == 0 {
            return Err(invalid_model(
                "PET edge combination VJP max edges per atom must be nonzero",
            ));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET edge combination VJP slot count overflows"))?;
        let dims = self.runtime_dims_from_payload()?;
        let d_edge = dims.d_edge;
        let pair_edge_dim = 2 * d_edge;
        expect_shape_len(
            "edge combination VJP output_edge_embeddings",
            output_edge_embeddings,
            edge_slots,
            d_edge,
        )?;
        expect_shape_len(
            "edge combination VJP bar_combination_update",
            bar_combination_update,
            edge_slots,
            d_edge,
        )?;
        expect_shape_len(
            "edge combination VJP bar_next_edge_embeddings",
            bar_next_edge_embeddings,
            edge_slots,
            d_edge,
        )?;

        let reversed_edge_embeddings = Self::reverse_edge_embeddings(
            output_edge_embeddings,
            n_atoms,
            max_edges_per_atom,
            d_edge,
            reverse_neighbor_index,
        )?;
        let mut pre_norm = Vec::with_capacity(edge_slots * pair_edge_dim);
        for edge in 0..edge_slots {
            let start = edge * d_edge;
            let end = start + d_edge;
            pre_norm.extend_from_slice(&output_edge_embeddings[start..end]);
            pre_norm.extend_from_slice(&reversed_edge_embeddings[start..end]);
        }
        let mut normalized = pre_norm.clone();
        layer_norm_rows(
            &mut normalized,
            edge_slots,
            pair_edge_dim,
            self.float_tensor(
                &format!("model.combination_norms.{layer}.weight"),
                &[pair_edge_dim],
            )?,
            self.float_tensor(
                &format!("model.combination_norms.{layer}.bias"),
                &[pair_edge_dim],
            )?,
            PET_MAD_XS_LAYER_NORM_EPS,
        )?;

        let first_weight = self.float_tensor(
            &format!("model.combination_mlps.{layer}.0.weight"),
            &[pair_edge_dim, pair_edge_dim],
        )?;
        let first_bias = self.float_tensor(
            &format!("model.combination_mlps.{layer}.0.bias"),
            &[pair_edge_dim],
        )?;
        let second_weight = self.float_tensor(
            &format!("model.combination_mlps.{layer}.2.weight"),
            &[d_edge, pair_edge_dim],
        )?;

        let first_preactivation = dense_forward(
            &normalized,
            edge_slots,
            pair_edge_dim,
            first_weight,
            first_bias,
        )?;
        let bar_update_total = bar_combination_update
            .iter()
            .zip(bar_next_edge_embeddings)
            .map(|(left, right)| left + right)
            .collect::<Vec<_>>();
        let bar_hidden = dense_input_vjp(
            &bar_update_total,
            edge_slots,
            pair_edge_dim,
            second_weight,
            d_edge,
        )?;
        let bar_first_preactivation = silu_vjp(&first_preactivation, &bar_hidden)?;
        let bar_normalized = dense_input_vjp(
            &bar_first_preactivation,
            edge_slots,
            pair_edge_dim,
            first_weight,
            pair_edge_dim,
        )?;
        let bar_pre_norm = layer_norm_rows_input_vjp(
            &pre_norm,
            edge_slots,
            pair_edge_dim,
            self.float_tensor(
                &format!("model.combination_norms.{layer}.weight"),
                &[pair_edge_dim],
            )?,
            &bar_normalized,
            PET_MAD_XS_LAYER_NORM_EPS,
        )?;

        let mut bar_output_edge_embeddings = bar_next_edge_embeddings.to_vec();
        for (atom, row) in reverse_neighbor_index.iter().enumerate() {
            for (edge, &source_slot) in row.iter().enumerate() {
                if source_slot >= edge_slots {
                    return Err(invalid_model(format!(
                        "reverse_neighbor_index[{atom}][{edge}]={source_slot} is out of bounds for {edge_slots} flattened edge slots"
                    )));
                }
                let edge_slot = atom * max_edges_per_atom + edge;
                let edge_start = edge_slot * d_edge;
                let source_start = source_slot * d_edge;
                let pre_norm_start = edge_slot * pair_edge_dim;
                let reversed_start = pre_norm_start + d_edge;
                for component in 0..d_edge {
                    bar_output_edge_embeddings[edge_start + component] +=
                        bar_pre_norm[pre_norm_start + component];
                    bar_output_edge_embeddings[source_start + component] +=
                        bar_pre_norm[reversed_start + component];
                }
            }
        }

        Ok(PetLiteEdgeCombinationVjp {
            bar_input_edge_embeddings: bar_next_edge_embeddings.to_vec(),
            bar_output_edge_embeddings,
        })
    }

