    #[allow(clippy::too_many_arguments)]
    pub fn energy_tail_vjp(
        &self,
        node_embeddings: &[f64],
        edge_embeddings: &[f64],
        element_indices_nodes: &[usize],
        system_indices: &[usize],
        padding_mask: &[bool],
        cutoff_factors: &[f64],
        bar_postprocessed_per_system: &[f64],
        num_systems: usize,
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<PetLiteEnergyTailVjp, PetLiteError> {
        self.energy_tail_vjp_with_active_rows(
            node_embeddings,
            edge_embeddings,
            element_indices_nodes,
            system_indices,
            padding_mask,
            cutoff_factors,
            bar_postprocessed_per_system,
            num_systems,
            n_atoms,
            max_edges_per_atom,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn energy_tail_vjp_with_active_rows(
        &self,
        node_embeddings: &[f64],
        edge_embeddings: &[f64],
        element_indices_nodes: &[usize],
        system_indices: &[usize],
        padding_mask: &[bool],
        cutoff_factors: &[f64],
        bar_postprocessed_per_system: &[f64],
        num_systems: usize,
        n_atoms: usize,
        max_edges_per_atom: usize,
        precomputed_active_edge_rows: Option<&PetLiteActiveEdgeMetadata>,
    ) -> Result<PetLiteEnergyTailVjp, PetLiteError> {
        if num_systems == 0 {
            return Err(invalid_model(
                "PET energy-tail VJP system count must be nonzero",
            ));
        }
        if element_indices_nodes.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET energy-tail VJP element_indices_nodes length must be {n_atoms}, got {}",
                element_indices_nodes.len()
            )));
        }
        if system_indices.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET energy-tail VJP system_indices length must be {n_atoms}, got {}",
                system_indices.len()
            )));
        }
        expect_len(
            "energy-tail VJP bar_postprocessed_per_system",
            bar_postprocessed_per_system,
            num_systems,
            1,
        )?;
        let postprocessing = self
            .energy_postprocessing
            .as_ref()
            .ok_or_else(|| invalid_model("PET energy post-processing metadata is not available"))?;
        let dims = self.runtime_dims_from_payload()?;
        let d_node = dims.d_node;
        let d_edge = dims.d_edge;
        let energy_hidden = dims.energy_head_hidden;
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET energy-tail VJP edge slot count overflows"))?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET energy-tail VJP padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        expect_shape_len(
            "PET energy-tail VJP cutoff_factors",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        let active_edge_rows = if dims.uses_active_edge_compaction_for(edge_slots) {
            if let Some(metadata) = precomputed_active_edge_rows {
                metadata.rows().map(Arc::clone)
            } else {
                active_edge_row_indices(edge_slots, padding_mask).map(Arc::<[usize]>::from)
            }
        } else {
            None
        };

        let feature_cache = self.energy_last_layer_features_cached(
            node_embeddings,
            edge_embeddings,
            n_atoms,
            max_edges_per_atom,
            active_edge_rows.as_ref(),
        )?;
        let node_prediction_weight = self.float_tensor(
            "model.node_last_layers.energy.0.energy___0.weight",
            &[1, d_edge],
        )?;
        let node_atomic_predictions = dense_forward(
            &feature_cache.node_last_layer_features,
            n_atoms,
            d_edge,
            node_prediction_weight,
            self.float_tensor("model.node_last_layers.energy.0.energy___0.bias", &[1])?,
        )?;
        let edge_prediction_weight = self.float_tensor(
            "model.edge_last_layers.energy.0.energy___0.weight",
            &[1, d_edge],
        )?;
        let edge_prediction_bias =
            self.float_tensor("model.edge_last_layers.energy.0.energy___0.bias", &[1])?;
        let (edge_atomic_predictions, compact_edge_predictions, edge_predictions_by_slot) =
            if let Some(active_rows) = &feature_cache.edge_active_rows {
                let compact_edge_features = feature_cache
                    .compact_edge_last_layer_features
                    .as_ref()
                    .ok_or_else(|| {
                        invalid_model(
                            "PET energy-tail compact edge last-layer features are unavailable",
                        )
                    })?;
                expect_shape_len(
                    "PET energy-tail compact edge last-layer features",
                    compact_edge_features,
                    active_rows.len(),
                    d_edge,
                )?;
                let compact_predictions = dense_forward(
                    compact_edge_features,
                    active_rows.len(),
                    d_edge,
                    edge_prediction_weight,
                    edge_prediction_bias,
                )?;
                let edge_atomic_predictions = Self::reduce_active_edge_predictions(
                    active_rows.as_ref(),
                    &compact_predictions,
                    cutoff_factors,
                    n_atoms,
                    max_edges_per_atom,
                )?;
                (
                    edge_atomic_predictions,
                    Some(compact_predictions),
                    None::<Vec<f64>>,
                )
            } else {
                let edge_predictions_by_slot = dense_forward(
                    &feature_cache.edge_last_layer_features,
                    edge_slots,
                    d_edge,
                    edge_prediction_weight,
                    edge_prediction_bias,
                )?;
                let edge_atomic_predictions = Self::reduce_edge_predictions_by_slot(
                    &edge_predictions_by_slot,
                    cutoff_factors,
                    padding_mask,
                    n_atoms,
                    max_edges_per_atom,
                )?;
                (
                    edge_atomic_predictions,
                    None::<Vec<f64>>,
                    Some(edge_predictions_by_slot),
                )
            };
        let unscaled_per_atom =
            Self::combine_atomic_predictions(&node_atomic_predictions, &edge_atomic_predictions)?;
        let postprocessed = self.apply_energy_postprocessing(
            element_indices_nodes,
            system_indices,
            &unscaled_per_atom,
            num_systems,
        )?;

        let mut bar_unscaled_per_atom = Vec::with_capacity(n_atoms);
        for (atom, &system_index) in system_indices.iter().enumerate() {
            if system_index >= num_systems {
                return Err(invalid_model(format!(
                    "system_indices[{atom}]={system_index} is out of bounds for {num_systems} systems"
                )));
            }
            bar_unscaled_per_atom
                .push(bar_postprocessed_per_system[system_index] * postprocessing.scale.value);
        }

        let bar_node_last_layer_features = dense_input_vjp(
            &bar_unscaled_per_atom,
            n_atoms,
            d_edge,
            node_prediction_weight,
            1,
        )?;
        let (
            bar_edge_last_layer_features,
            compact_bar_edge_last_layer_features,
            bar_cutoff_factors,
        ) = if let Some(active_rows) = &feature_cache.edge_active_rows {
            let compact_edge_predictions = compact_edge_predictions.as_ref().ok_or_else(|| {
                invalid_model("PET energy-tail VJP compact edge predictions are unavailable")
            })?;
            let (compact_bar_edge_predictions, bar_cutoff_factors) =
                Self::active_edge_prediction_vjp(
                    active_rows.as_ref(),
                    compact_edge_predictions,
                    cutoff_factors,
                    &bar_unscaled_per_atom,
                    n_atoms,
                    max_edges_per_atom,
                )?;
            let compact_bar_edge_last_layer_features = dense_input_vjp(
                &compact_bar_edge_predictions,
                active_rows.len(),
                d_edge,
                edge_prediction_weight,
                1,
            )?;
            (
                Vec::new(),
                Some(compact_bar_edge_last_layer_features),
                bar_cutoff_factors,
            )
        } else {
            let edge_predictions_by_slot = edge_predictions_by_slot.as_ref().ok_or_else(|| {
                invalid_model("PET energy-tail VJP edge predictions by slot are unavailable")
            })?;
            let mut bar_edge_predictions_by_slot = vec![0.0; edge_slots];
            let mut bar_cutoff_factors = vec![0.0; edge_slots];
            for (atom, &bar_value) in bar_unscaled_per_atom.iter().enumerate().take(n_atoms) {
                for edge in 0..max_edges_per_atom {
                    let edge_slot = atom * max_edges_per_atom + edge;
                    if padding_mask[edge_slot] {
                        bar_edge_predictions_by_slot[edge_slot] +=
                            bar_value * cutoff_factors[edge_slot];
                        bar_cutoff_factors[edge_slot] +=
                            bar_value * edge_predictions_by_slot[edge_slot];
                    }
                }
            }
            let bar_edge_last_layer_features = dense_input_vjp(
                &bar_edge_predictions_by_slot,
                edge_slots,
                d_edge,
                edge_prediction_weight,
                1,
            )?;
            (
                bar_edge_last_layer_features,
                None::<Vec<f64>>,
                bar_cutoff_factors,
            )
        };

        let node_head_second_weight = self.float_tensor(
            "model.node_heads.energy.0.2.weight",
            &[d_edge, energy_hidden],
        )?;
        let node_head_first_weight = self.float_tensor(
            "model.node_heads.energy.0.0.weight",
            &[energy_hidden, d_node],
        )?;
        let bar_node_second_preactivation = silu_vjp_from_sigmoid(
            &feature_cache.node_second_preactivation,
            &feature_cache.node_second_sigmoid,
            &bar_node_last_layer_features,
        )?;
        let bar_node_first_activation = dense_input_vjp(
            &bar_node_second_preactivation,
            n_atoms,
            energy_hidden,
            node_head_second_weight,
            d_edge,
        )?;
        let bar_node_first_preactivation = silu_vjp_from_sigmoid(
            &feature_cache.node_first_preactivation,
            &feature_cache.node_first_sigmoid,
            &bar_node_first_activation,
        )?;
        let bar_node_embeddings = dense_input_vjp(
            &bar_node_first_preactivation,
            n_atoms,
            d_node,
            node_head_first_weight,
            energy_hidden,
        )?;

        let edge_head_second_weight = self.float_tensor(
            "model.edge_heads.energy.0.2.weight",
            &[d_edge, energy_hidden],
        )?;
        let edge_head_first_weight = self.float_tensor(
            "model.edge_heads.energy.0.0.weight",
            &[energy_hidden, d_edge],
        )?;
        let bar_edge_embeddings = if let Some(active_rows) = &feature_cache.edge_active_rows {
            expect_selected_rows("energy-tail VJP edge active rows", active_rows, edge_slots)?;
            let compact_bar_edge_last_layer_features = compact_bar_edge_last_layer_features
                .as_ref()
                .ok_or_else(|| {
                    invalid_model(
                        "PET energy-tail VJP compact bar edge last-layer features are unavailable",
                    )
                })?;
            let bar_edge_second_preactivation = silu_vjp_from_sigmoid(
                &feature_cache.edge_second_preactivation,
                &feature_cache.edge_second_sigmoid,
                compact_bar_edge_last_layer_features,
            )?;
            let bar_edge_first_activation = dense_input_vjp(
                &bar_edge_second_preactivation,
                active_rows.len(),
                energy_hidden,
                edge_head_second_weight,
                d_edge,
            )?;
            let bar_edge_first_preactivation = silu_vjp_from_sigmoid(
                &feature_cache.edge_first_preactivation,
                &feature_cache.edge_first_sigmoid,
                &bar_edge_first_activation,
            )?;
            let compact_bar_edge_embeddings = dense_input_vjp(
                &bar_edge_first_preactivation,
                active_rows.len(),
                d_edge,
                edge_head_first_weight,
                energy_hidden,
            )?;
            scatter_selected_rows_to_padded(
                &compact_bar_edge_embeddings,
                edge_slots,
                d_edge,
                active_rows,
                "energy-tail VJP bar_edge_embeddings",
            )?
        } else {
            let bar_edge_second_preactivation = silu_vjp_from_sigmoid(
                &feature_cache.edge_second_preactivation,
                &feature_cache.edge_second_sigmoid,
                &bar_edge_last_layer_features,
            )?;
            let bar_edge_first_activation = dense_input_vjp(
                &bar_edge_second_preactivation,
                edge_slots,
                energy_hidden,
                edge_head_second_weight,
                d_edge,
            )?;
            let bar_edge_first_preactivation = silu_vjp_from_sigmoid(
                &feature_cache.edge_first_preactivation,
                &feature_cache.edge_first_sigmoid,
                &bar_edge_first_activation,
            )?;
            dense_input_vjp(
                &bar_edge_first_preactivation,
                edge_slots,
                d_edge,
                edge_head_first_weight,
                energy_hidden,
            )?
        };

        Ok(PetLiteEnergyTailVjp {
            bar_node_embeddings,
            bar_edge_embeddings,
            bar_cutoff_factors,
            bar_unscaled_per_atom,
            postprocessed_per_system: postprocessed.per_system,
        })
    }

    #[doc(hidden)]
    #[allow(clippy::too_many_arguments)]
    pub fn energy_tail_vjp_f32(
        &self,
        node_embeddings: &[f32],
        edge_embeddings: &[f32],
        element_indices_nodes: &[usize],
        system_indices: &[usize],
        padding_mask: &[bool],
        cutoff_factors: &[f32],
        bar_postprocessed_per_system: &[f64],
        num_systems: usize,
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<PetLiteEnergyTailVjpF32, PetLiteError> {
        self.energy_tail_vjp_f32_with_active_rows(
            node_embeddings,
            edge_embeddings,
            element_indices_nodes,
            system_indices,
            padding_mask,
            cutoff_factors,
            bar_postprocessed_per_system,
            num_systems,
            n_atoms,
            max_edges_per_atom,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn energy_tail_vjp_f32_with_active_rows(
        &self,
        node_embeddings: &[f32],
        edge_embeddings: &[f32],
        element_indices_nodes: &[usize],
        system_indices: &[usize],
        padding_mask: &[bool],
        cutoff_factors: &[f32],
        bar_postprocessed_per_system: &[f64],
        num_systems: usize,
        n_atoms: usize,
        max_edges_per_atom: usize,
        precomputed_active_edge_rows: Option<&PetLiteActiveEdgeMetadata>,
    ) -> Result<PetLiteEnergyTailVjpF32, PetLiteError> {
        if num_systems == 0 {
            return Err(invalid_model(
                "PET f32 energy-tail VJP system count must be nonzero",
            ));
        }
        if element_indices_nodes.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET f32 energy-tail VJP element_indices_nodes length must be {n_atoms}, got {}",
                element_indices_nodes.len()
            )));
        }
        if system_indices.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET f32 energy-tail VJP system_indices length must be {n_atoms}, got {}",
                system_indices.len()
            )));
        }
        expect_len(
            "PET f32 energy-tail VJP bar_postprocessed_per_system",
            bar_postprocessed_per_system,
            num_systems,
            1,
        )?;
        let postprocessing = self.energy_postprocessing.as_ref().ok_or_else(|| {
            invalid_model("PET f32 energy post-processing metadata is not available")
        })?;
        let dims = self.runtime_dims_from_payload()?;
        let d_node = dims.d_node;
        let d_edge = dims.d_edge;
        let energy_hidden = dims.energy_head_hidden;
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 energy-tail VJP edge slot count overflows"))?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET f32 energy-tail VJP padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        expect_shape_len_f32(
            "PET f32 energy-tail VJP cutoff_factors",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        let active_edge_rows = if dims.uses_active_edge_compaction_for(edge_slots) {
            if let Some(metadata) = precomputed_active_edge_rows {
                metadata.rows().map(Arc::clone)
            } else {
                active_edge_row_indices(edge_slots, padding_mask).map(Arc::<[usize]>::from)
            }
        } else {
            None
        };

        let feature_cache = self.energy_last_layer_features_cached_f32(
            node_embeddings,
            edge_embeddings,
            n_atoms,
            max_edges_per_atom,
            active_edge_rows.as_ref(),
        )?;
        let node_prediction_weight = self.float_tensor_f32(
            "model.node_last_layers.energy.0.energy___0.weight",
            &[1, d_edge],
        )?;
        let node_atomic_predictions = dense_forward_f32(
            &feature_cache.node_last_layer_features,
            n_atoms,
            d_edge,
            node_prediction_weight,
            self.float_tensor_f32("model.node_last_layers.energy.0.energy___0.bias", &[1])?,
        )?;
        let edge_prediction_weight = self.float_tensor_f32(
            "model.edge_last_layers.energy.0.energy___0.weight",
            &[1, d_edge],
        )?;
        let edge_prediction_bias =
            self.float_tensor_f32("model.edge_last_layers.energy.0.energy___0.bias", &[1])?;
        let (edge_atomic_predictions, compact_edge_predictions, edge_predictions_by_slot) =
            if let Some(active_rows) = &feature_cache.edge_active_rows {
                let compact_edge_features = feature_cache
                    .compact_edge_last_layer_features
                    .as_ref()
                    .ok_or_else(|| {
                        invalid_model(
                            "PET f32 energy-tail compact edge last-layer features are unavailable",
                        )
                    })?;
                expect_shape_len_f32(
                    "PET f32 energy-tail compact edge last-layer features",
                    compact_edge_features,
                    active_rows.len(),
                    d_edge,
                )?;
                let compact_predictions = dense_forward_f32(
                    compact_edge_features,
                    active_rows.len(),
                    d_edge,
                    edge_prediction_weight,
                    edge_prediction_bias,
                )?;
                let edge_atomic_predictions = Self::reduce_active_edge_predictions_f32(
                    active_rows.as_ref(),
                    &compact_predictions,
                    cutoff_factors,
                    n_atoms,
                    max_edges_per_atom,
                )?;
                (
                    edge_atomic_predictions,
                    Some(compact_predictions),
                    None::<Vec<f32>>,
                )
            } else {
                let edge_predictions_by_slot = dense_forward_f32(
                    &feature_cache.edge_last_layer_features,
                    edge_slots,
                    d_edge,
                    edge_prediction_weight,
                    edge_prediction_bias,
                )?;
                let edge_atomic_predictions = Self::reduce_edge_predictions_by_slot_f32(
                    &edge_predictions_by_slot,
                    cutoff_factors,
                    padding_mask,
                    n_atoms,
                    max_edges_per_atom,
                )?;
                (
                    edge_atomic_predictions,
                    None::<Vec<f32>>,
                    Some(edge_predictions_by_slot),
                )
            };
        let unscaled_per_atom = Self::combine_atomic_predictions_f32_to_f64(
            &node_atomic_predictions,
            &edge_atomic_predictions,
        )?;
        let postprocessed = self.apply_energy_postprocessing(
            element_indices_nodes,
            system_indices,
            &unscaled_per_atom,
            num_systems,
        )?;

        let scale = postprocessing.scale.value;
        let mut bar_unscaled_per_atom = Vec::with_capacity(n_atoms);
        for (atom, &system_index) in system_indices.iter().enumerate() {
            if system_index >= num_systems {
                return Err(invalid_model(format!(
                    "system_indices[{atom}]={system_index} is out of bounds for {num_systems} systems"
                )));
            }
            bar_unscaled_per_atom.push((bar_postprocessed_per_system[system_index] * scale) as f32);
        }

        let bar_node_last_layer_features = dense_input_vjp_f32(
            &bar_unscaled_per_atom,
            n_atoms,
            d_edge,
            node_prediction_weight,
            1,
        )?;
        let (
            bar_edge_last_layer_features,
            compact_bar_edge_last_layer_features,
            bar_cutoff_factors,
        ) = if let Some(active_rows) = &feature_cache.edge_active_rows {
            let compact_edge_predictions = compact_edge_predictions.as_ref().ok_or_else(|| {
                invalid_model("PET f32 energy-tail VJP compact edge predictions are unavailable")
            })?;
            let (compact_bar_edge_predictions, bar_cutoff_factors) =
                Self::active_edge_prediction_vjp_f32(
                    active_rows.as_ref(),
                    compact_edge_predictions,
                    cutoff_factors,
                    &bar_unscaled_per_atom,
                    n_atoms,
                    max_edges_per_atom,
                )?;
            let compact_bar_edge_last_layer_features = dense_input_vjp_f32(
                &compact_bar_edge_predictions,
                active_rows.len(),
                d_edge,
                edge_prediction_weight,
                1,
            )?;
            (
                Vec::new(),
                Some(compact_bar_edge_last_layer_features),
                bar_cutoff_factors,
            )
        } else {
            let edge_predictions_by_slot = edge_predictions_by_slot.as_ref().ok_or_else(|| {
                invalid_model("PET f32 energy-tail VJP edge predictions by slot are unavailable")
            })?;
            let mut bar_edge_predictions_by_slot = vec![0.0; edge_slots];
            let mut bar_cutoff_factors = vec![0.0; edge_slots];
            for (atom, &bar_value) in bar_unscaled_per_atom.iter().enumerate().take(n_atoms) {
                for edge in 0..max_edges_per_atom {
                    let edge_slot = atom * max_edges_per_atom + edge;
                    if padding_mask[edge_slot] {
                        bar_edge_predictions_by_slot[edge_slot] +=
                            bar_value * cutoff_factors[edge_slot];
                        bar_cutoff_factors[edge_slot] +=
                            bar_value * edge_predictions_by_slot[edge_slot];
                    }
                }
            }
            let bar_edge_last_layer_features = dense_input_vjp_f32(
                &bar_edge_predictions_by_slot,
                edge_slots,
                d_edge,
                edge_prediction_weight,
                1,
            )?;
            (
                bar_edge_last_layer_features,
                None::<Vec<f32>>,
                bar_cutoff_factors,
            )
        };

        let node_head_second_weight = self.float_tensor_f32(
            "model.node_heads.energy.0.2.weight",
            &[d_edge, energy_hidden],
        )?;
        let node_head_first_weight = self.float_tensor_f32(
            "model.node_heads.energy.0.0.weight",
            &[energy_hidden, d_node],
        )?;
        let bar_node_second_preactivation = silu_vjp_from_sigmoid_f32(
            &feature_cache.node_second_preactivation,
            &feature_cache.node_second_sigmoid,
            &bar_node_last_layer_features,
        )?;
        let bar_node_first_activation = dense_input_vjp_f32(
            &bar_node_second_preactivation,
            n_atoms,
            energy_hidden,
            node_head_second_weight,
            d_edge,
        )?;
        let bar_node_first_preactivation = silu_vjp_from_sigmoid_f32(
            &feature_cache.node_first_preactivation,
            &feature_cache.node_first_sigmoid,
            &bar_node_first_activation,
        )?;
        let bar_node_embeddings = dense_input_vjp_f32(
            &bar_node_first_preactivation,
            n_atoms,
            d_node,
            node_head_first_weight,
            energy_hidden,
        )?;

        let edge_head_second_weight = self.float_tensor_f32(
            "model.edge_heads.energy.0.2.weight",
            &[d_edge, energy_hidden],
        )?;
        let edge_head_first_weight = self.float_tensor_f32(
            "model.edge_heads.energy.0.0.weight",
            &[energy_hidden, d_edge],
        )?;
        let bar_edge_embeddings = if let Some(active_rows) = &feature_cache.edge_active_rows {
            expect_selected_rows(
                "PET f32 energy-tail VJP edge active rows",
                active_rows,
                edge_slots,
            )?;
            let compact_bar_edge_last_layer_features =
                compact_bar_edge_last_layer_features.as_ref().ok_or_else(|| {
                    invalid_model(
                        "PET f32 energy-tail VJP compact bar edge last-layer features are unavailable",
                    )
                })?;
            let bar_edge_second_preactivation = silu_vjp_from_sigmoid_f32(
                &feature_cache.edge_second_preactivation,
                &feature_cache.edge_second_sigmoid,
                compact_bar_edge_last_layer_features,
            )?;
            let bar_edge_first_activation = dense_input_vjp_f32(
                &bar_edge_second_preactivation,
                active_rows.len(),
                energy_hidden,
                edge_head_second_weight,
                d_edge,
            )?;
            let bar_edge_first_preactivation = silu_vjp_from_sigmoid_f32(
                &feature_cache.edge_first_preactivation,
                &feature_cache.edge_first_sigmoid,
                &bar_edge_first_activation,
            )?;
            let compact_bar_edge_embeddings = dense_input_vjp_f32(
                &bar_edge_first_preactivation,
                active_rows.len(),
                d_edge,
                edge_head_first_weight,
                energy_hidden,
            )?;
            scatter_selected_rows_to_padded_f32(
                &compact_bar_edge_embeddings,
                edge_slots,
                d_edge,
                active_rows,
                "PET f32 energy-tail VJP bar_edge_embeddings",
            )?
        } else {
            let bar_edge_second_preactivation = silu_vjp_from_sigmoid_f32(
                &feature_cache.edge_second_preactivation,
                &feature_cache.edge_second_sigmoid,
                &bar_edge_last_layer_features,
            )?;
            let bar_edge_first_activation = dense_input_vjp_f32(
                &bar_edge_second_preactivation,
                edge_slots,
                energy_hidden,
                edge_head_second_weight,
                d_edge,
            )?;
            let bar_edge_first_preactivation = silu_vjp_from_sigmoid_f32(
                &feature_cache.edge_first_preactivation,
                &feature_cache.edge_first_sigmoid,
                &bar_edge_first_activation,
            )?;
            dense_input_vjp_f32(
                &bar_edge_first_preactivation,
                edge_slots,
                d_edge,
                edge_head_first_weight,
                energy_hidden,
            )?
        };

        Ok(PetLiteEnergyTailVjpF32 {
            bar_node_embeddings,
            bar_edge_embeddings,
            bar_cutoff_factors,
            bar_unscaled_per_atom,
            postprocessed_per_system: postprocessed.per_system,
        })
    }

    #[allow(clippy::too_many_arguments)]
    pub fn unscaled_energy_for_batch(
        &self,
        element_indices_nodes: &[usize],
        element_indices_neighbors: &[Vec<usize>],
        reverse_neighbor_index: &[Vec<usize>],
        system_indices: &[usize],
        edge_vectors: &[f64],
        edge_distances: &[f64],
        padding_mask: &[bool],
        cutoff_factors: &[f64],
        num_systems: usize,
    ) -> Result<PetLiteUnscaledEnergy, PetLiteError> {
        self.unscaled_energy_for_batch_profiled(
            element_indices_nodes,
            element_indices_neighbors,
            reverse_neighbor_index,
            system_indices,
            edge_vectors,
            edge_distances,
            padding_mask,
            cutoff_factors,
            num_systems,
            None,
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn unscaled_energy_for_batch_profiled(
        &self,
        element_indices_nodes: &[usize],
        element_indices_neighbors: &[Vec<usize>],
        reverse_neighbor_index: &[Vec<usize>],
        system_indices: &[usize],
        edge_vectors: &[f64],
        edge_distances: &[f64],
        padding_mask: &[bool],
        cutoff_factors: &[f64],
        num_systems: usize,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<PetLiteUnscaledEnergy, PetLiteError> {
        if num_systems == 0 {
            return Err(invalid_model(
                "PET unscaled energy system count must be nonzero",
            ));
        }
        let n_atoms = element_indices_nodes.len();
        if n_atoms == 0 {
            return Err(invalid_model(
                "PET unscaled energy atom count must be nonzero",
            ));
        }
        let max_edges_per_atom = element_indices_neighbors
            .first()
            .map_or(0, std::vec::Vec::len);
        if max_edges_per_atom == 0 {
            return Err(invalid_model(
                "PET unscaled energy max edges per atom must be nonzero",
            ));
        }
        validate_rectangular_usize_matrix(
            element_indices_neighbors,
            n_atoms,
            max_edges_per_atom,
            "element_indices_neighbors",
        )?;
        validate_rectangular_usize_matrix(
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            "reverse_neighbor_index",
        )?;
        if system_indices.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET unscaled energy system_indices length must be {n_atoms}, got {}",
                system_indices.len()
            )));
        }
        let dims = self.runtime_dims_from_payload()?;
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET unscaled energy edge slot count overflows"))?;
        expect_shape_len("PET unscaled edge_vectors", edge_vectors, edge_slots, 3)?;
        expect_shape_len("PET unscaled edge_distances", edge_distances, edge_slots, 1)?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET unscaled padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        expect_shape_len("PET unscaled cutoff_factors", cutoff_factors, edge_slots, 1)?;
        let precomputed_active_edge_metadata = dims
            .uses_active_edge_compaction_for(edge_slots)
            .then(|| active_edge_metadata(edge_slots, padding_mask));
        let precomputed_edge_combination_active_metadata =
            precomputed_active_edge_metadata.as_ref().map(|metadata| {
                active_edge_combination_metadata(
                    metadata,
                    padding_mask,
                    reverse_neighbor_index,
                    max_edges_per_atom,
                )
            });
        let precomputed_attention_metadata = Some(attention_metadata(
            n_atoms,
            max_edges_per_atom,
            padding_mask,
            dims.num_heads,
            should_cache_attention_probabilities(max_edges_per_atom + 1),
        )?);

        let stage_start = Instant::now();
        let mut node_embeddings = self.input_node_embeddings(element_indices_nodes)?;
        let mut edge_embeddings = self.input_edge_embeddings(element_indices_neighbors)?;
        if let Some(profile) = &mut profile {
            profile.forward.input_embeddings.record(stage_start);
        }
        for layer in 0..self.gnn_layers() {
            let stage_start = Instant::now();
            let (next_node_embeddings, output_edge_embeddings) = self.gnn_layer_forward_profiled(
                layer,
                node_embeddings,
                &edge_embeddings,
                element_indices_neighbors,
                edge_vectors,
                edge_distances,
                padding_mask,
                cutoff_factors,
                n_atoms,
                max_edges_per_atom,
                precomputed_active_edge_metadata.as_ref(),
                precomputed_attention_metadata.as_ref(),
                profile.as_deref_mut(),
            )?;
            if let Some(profile) = &mut profile {
                profile.forward_gnn_layer_mut(layer).record(stage_start);
            }
            let stage_start = Instant::now();
            let (_, next_edge_embeddings, _) = self.gnn_edge_combination_cached(
                layer,
                &edge_embeddings,
                &output_edge_embeddings,
                reverse_neighbor_index,
                n_atoms,
                max_edges_per_atom,
                Some(padding_mask),
                precomputed_edge_combination_active_metadata.as_ref(),
                false,
            )?;
            if let Some(profile) = &mut profile {
                profile
                    .forward_edge_combination_mut(layer)
                    .record(stage_start);
            }
            node_embeddings = next_node_embeddings;
            edge_embeddings = next_edge_embeddings;
        }
        let stage_start = Instant::now();
        let feature_cache = self.energy_last_layer_features_cached(
            &node_embeddings,
            &edge_embeddings,
            n_atoms,
            max_edges_per_atom,
            precomputed_active_edge_metadata
                .as_ref()
                .and_then(PetLiteActiveEdgeMetadata::rows),
        )?;
        let node_prediction_weight = self.float_tensor(
            "model.node_last_layers.energy.0.energy___0.weight",
            &[1, dims.d_edge],
        )?;
        let node_atomic_predictions = dense_forward(
            &feature_cache.node_last_layer_features,
            n_atoms,
            dims.d_edge,
            node_prediction_weight,
            self.float_tensor("model.node_last_layers.energy.0.energy___0.bias", &[1])?,
        )?;
        let edge_prediction_weight = self.float_tensor(
            "model.edge_last_layers.energy.0.energy___0.weight",
            &[1, dims.d_edge],
        )?;
        let edge_prediction_bias =
            self.float_tensor("model.edge_last_layers.energy.0.energy___0.bias", &[1])?;
        let edge_atomic_predictions = if let Some(active_rows) = &feature_cache.edge_active_rows {
            let compact_edge_features = feature_cache
                .compact_edge_last_layer_features
                .as_ref()
                .ok_or_else(|| {
                    invalid_model(
                        "PET unscaled energy compact edge last-layer features are unavailable",
                    )
                })?;
            expect_shape_len(
                "PET unscaled energy compact edge last-layer features",
                compact_edge_features,
                active_rows.len(),
                dims.d_edge,
            )?;
            let compact_predictions = dense_forward(
                compact_edge_features,
                active_rows.len(),
                dims.d_edge,
                edge_prediction_weight,
                edge_prediction_bias,
            )?;
            Self::reduce_active_edge_predictions(
                active_rows.as_ref(),
                &compact_predictions,
                cutoff_factors,
                n_atoms,
                max_edges_per_atom,
            )?
        } else {
            let edge_predictions_by_slot = dense_forward(
                &feature_cache.edge_last_layer_features,
                edge_slots,
                dims.d_edge,
                edge_prediction_weight,
                edge_prediction_bias,
            )?;
            Self::reduce_edge_predictions_by_slot(
                &edge_predictions_by_slot,
                cutoff_factors,
                padding_mask,
                n_atoms,
                max_edges_per_atom,
            )?
        };
        let per_atom =
            Self::combine_atomic_predictions(&node_atomic_predictions, &edge_atomic_predictions)?;
        let per_system =
            Self::sum_per_atom_predictions_by_system(&per_atom, system_indices, num_systems, 1)?;
        if let Some(profile) = &mut profile {
            profile
                .forward
                .energy_head_and_reduction
                .record(stage_start);
        }
        Ok(PetLiteUnscaledEnergy {
            node_atomic_predictions,
            edge_atomic_predictions,
            per_atom,
            per_system,
        })
    }

    #[doc(hidden)]
