    #[allow(clippy::too_many_arguments)]
    fn postprocessed_energy_vjp_for_batch_f32_profiled(
        &self,
        element_indices_nodes: &[usize],
        element_indices_neighbors: &[Vec<usize>],
        reverse_neighbor_index: &[Vec<usize>],
        system_indices: &[usize],
        edge_vectors: &[f32],
        edge_distances: &[f32],
        padding_mask: &[bool],
        cutoff_factors: &[f32],
        bar_postprocessed_per_system: &[f64],
        num_systems: usize,
        mut workspace: Option<&mut PetLiteForceWorkspace>,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<PetLiteBatchEnergyVjpF32, PetLiteError> {
        if num_systems == 0 {
            return Err(invalid_model(
                "PET f32 batch-energy VJP system count must be nonzero",
            ));
        }
        let runtime_dims = self.supported_runtime_dims()?;
        if !self.has_native_f32_state_tensors() {
            return Err(PetLiteError::UnsupportedComputeDtype(
                PredictionComputeDtype::Float32,
            ));
        }
        let n_atoms = element_indices_nodes.len();
        if n_atoms == 0 {
            return Err(invalid_model(
                "PET f32 batch-energy VJP atom count must be nonzero",
            ));
        }
        let max_edges_per_atom = element_indices_neighbors
            .first()
            .map_or(0, std::vec::Vec::len);
        if max_edges_per_atom == 0 {
            return Err(invalid_model(
                "PET f32 batch-energy VJP max edges per atom must be nonzero",
            ));
        }
        validate_rectangular_usize_matrix(
            element_indices_neighbors,
            n_atoms,
            max_edges_per_atom,
            "element_indices_neighbors",
        )?;
        validate_rectangular_usize_matrix(
            reverse_neighbor_index,
            n_atoms,
            max_edges_per_atom,
            "reverse_neighbor_index",
        )?;
        if system_indices.len() != n_atoms {
            return Err(invalid_model(format!(
                "PET f32 batch-energy VJP system_indices length must be {n_atoms}, got {}",
                system_indices.len()
            )));
        }
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 batch-energy VJP edge slot count overflows"))?;
        expect_shape_len_f32(
            "PET f32 batch-energy VJP edge_vectors",
            edge_vectors,
            edge_slots,
            3,
        )?;
        expect_shape_len_f32(
            "PET f32 batch-energy VJP edge_distances",
            edge_distances,
            edge_slots,
            1,
        )?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET f32 batch-energy VJP padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        expect_shape_len_f32(
            "PET f32 batch-energy VJP cutoff_factors",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        expect_shape_len(
            "PET f32 batch-energy VJP bar_postprocessed_per_system",
            bar_postprocessed_per_system,
            num_systems,
            1,
        )?;
        let precomputed_active_edge_metadata = runtime_dims
            .uses_active_edge_compaction_for(edge_slots)
            .then(|| active_edge_metadata(edge_slots, padding_mask));
        let precomputed_edge_combination_active_metadata =
            precomputed_active_edge_metadata.as_ref().map(|metadata| {
                active_edge_combination_metadata(
                    metadata,
                    padding_mask,
                    reverse_neighbor_index,
                    max_edges_per_atom,
                )
            });
        let precomputed_attention_metadata = Some(attention_metadata(
            n_atoms,
            max_edges_per_atom,
            padding_mask,
            runtime_dims.num_heads,
            should_cache_attention_probabilities(max_edges_per_atom + 1),
        )?);

        let mut gnn_forward_caches = Vec::with_capacity(self.gnn_layers());
        let mut edge_combination_caches = Vec::with_capacity(self.gnn_layers());
        let stage_start = Instant::now();
        let mut node_embeddings = if let Some(workspace) = workspace.as_deref_mut() {
            self.input_node_embeddings_f32_into_profiled(
                element_indices_nodes,
                &mut workspace.vjp_input_node_embeddings_f32,
                profile.as_deref_mut(),
            )?;
            std::mem::take(&mut workspace.vjp_input_node_embeddings_f32)
        } else {
            self.input_node_embeddings_f32(element_indices_nodes)?
        };
        let mut edge_embeddings = if let Some(workspace) = workspace.as_deref_mut() {
            self.input_edge_embeddings_f32_into_profiled(
                element_indices_neighbors,
                &mut workspace.vjp_input_edge_embeddings_f32,
                profile.as_deref_mut(),
            )?;
            std::mem::take(&mut workspace.vjp_input_edge_embeddings_f32)
        } else {
            self.input_edge_embeddings_f32(element_indices_neighbors)?
        };
        if let Some(profile) = &mut profile {
            profile.vjp.input_embeddings.record(stage_start);
        }
        for layer in 0..self.gnn_layers() {
            let stage_start = Instant::now();
            let mut forward_cache = self.gnn_layer_forward_cached_f32(
                layer,
                node_embeddings,
                &edge_embeddings,
                element_indices_neighbors,
                edge_vectors,
                edge_distances,
                padding_mask,
                cutoff_factors,
                n_atoms,
                max_edges_per_atom,
                precomputed_active_edge_metadata.as_ref(),
                precomputed_attention_metadata.as_ref(),
                profile.as_deref_mut(),
            )?;
            if let Some(profile) = &mut profile {
                profile
                    .vjp_gnn_forward_replay_mut(layer)
                    .record(stage_start);
            }
            let next_node_embeddings = std::mem::take(&mut forward_cache.output_node_embeddings);
            let output_edge_embeddings = std::mem::take(&mut forward_cache.output_edge_embeddings);
            let stage_start = Instant::now();
            let (_, next_edge_embeddings, edge_combination_cache) = self
                .gnn_edge_combination_cached_f32(
                    layer,
                    &edge_embeddings,
                    &output_edge_embeddings,
                    reverse_neighbor_index,
                    n_atoms,
                    max_edges_per_atom,
                    Some(padding_mask),
                    precomputed_edge_combination_active_metadata.as_ref(),
                    false,
                )?;
            if let Some(profile) = &mut profile {
                profile
                    .vjp_edge_combination_forward_mut(layer)
                    .record(stage_start);
            }
            edge_combination_caches.push(edge_combination_cache);
            gnn_forward_caches.push(forward_cache);
            node_embeddings = next_node_embeddings;
            edge_embeddings = next_edge_embeddings;
        }

        let stage_start = Instant::now();
        let tail_vjp = self.energy_tail_vjp_f32_with_active_rows(
            &node_embeddings,
            &edge_embeddings,
            element_indices_nodes,
            system_indices,
            padding_mask,
            cutoff_factors,
            bar_postprocessed_per_system,
            num_systems,
            n_atoms,
            max_edges_per_atom,
            precomputed_active_edge_metadata.as_ref(),
        )?;
        if let Some(profile) = &mut profile {
            profile.vjp.energy_tail_vjp.record(stage_start);
        }
        if let Some(workspace) = workspace.as_mut() {
            let workspace = &mut **workspace;
            workspace.vjp_input_node_embeddings_f32 = node_embeddings;
            workspace.vjp_input_edge_embeddings_f32 = edge_embeddings;
        }
        let mut bar_node_embeddings = tail_vjp.bar_node_embeddings;
        let mut bar_edge_embeddings = tail_vjp.bar_edge_embeddings;
        let mut bar_edge_vectors = if let Some(workspace) = workspace.as_mut() {
            let workspace = &mut **workspace;
            let stats = fill_f32_zero(&mut workspace.vjp_bar_edge_vectors_f32, edge_vectors.len());
            if let Some(profile) = &mut profile {
                profile.allocations.vjp_bar_edge_vectors_f32.record(stats);
            }
            std::mem::take(&mut workspace.vjp_bar_edge_vectors_f32)
        } else {
            vec![0.0; edge_vectors.len()]
        };
        let mut bar_edge_distances = if let Some(workspace) = workspace.as_mut() {
            let workspace = &mut **workspace;
            let stats = fill_f32_zero(
                &mut workspace.vjp_bar_edge_distances_f32,
                edge_distances.len(),
            );
            if let Some(profile) = &mut profile {
                profile.allocations.vjp_bar_edge_distances_f32.record(stats);
            }
            std::mem::take(&mut workspace.vjp_bar_edge_distances_f32)
        } else {
            vec![0.0; edge_distances.len()]
        };
        let mut bar_cutoff_factors = tail_vjp.bar_cutoff_factors;

        for layer in (0..self.gnn_layers()).rev() {
            let stage_start = Instant::now();
            let combination_vjp = self.gnn_edge_combination_vjp_from_cache_f32(
                layer,
                &edge_combination_caches[layer],
                reverse_neighbor_index,
                padding_mask,
                bar_edge_embeddings,
                n_atoms,
                max_edges_per_atom,
            )?;
            if let Some(profile) = &mut profile {
                profile.vjp_edge_combination_mut(layer).record(stage_start);
            }
            let PetLiteEdgeCombinationVjpF32 {
                bar_input_edge_embeddings: combination_bar_input_edge_embeddings,
                bar_output_edge_embeddings: combination_bar_output_edge_embeddings,
            } = combination_vjp;
            let stage_start = Instant::now();
            let layer_vjp = self.gnn_layer_forward_vjp_from_cache_f32(
                layer,
                &gnn_forward_caches[layer],
                element_indices_neighbors,
                edge_vectors,
                edge_distances,
                padding_mask,
                cutoff_factors,
                bar_node_embeddings,
                combination_bar_output_edge_embeddings,
                n_atoms,
                max_edges_per_atom,
                Some((&mut bar_edge_vectors, &mut bar_edge_distances)),
                Some(&mut bar_cutoff_factors),
                profile.as_deref_mut(),
            )?;
            if let Some(profile) = &mut profile {
                profile.vjp_gnn_layer_mut(layer).record(stage_start);
            }
            if !layer_vjp.bar_edge_vectors.is_empty() {
                add_assign_equal_len_f32(&mut bar_edge_vectors, &layer_vjp.bar_edge_vectors)?;
            }
            if !layer_vjp.bar_edge_distances.is_empty() {
                add_assign_equal_len_f32(&mut bar_edge_distances, &layer_vjp.bar_edge_distances)?;
            }
            if !layer_vjp.bar_cutoff_factors.is_empty() {
                add_assign_equal_len_f32(&mut bar_cutoff_factors, &layer_vjp.bar_cutoff_factors)?;
            }
            bar_node_embeddings = layer_vjp.bar_input_node_embeddings;
            bar_edge_embeddings = combination_bar_input_edge_embeddings;
            if layer > 0 {
                add_assign_equal_len_f32(
                    &mut bar_edge_embeddings,
                    &layer_vjp.bar_input_edge_embeddings,
                )?;
            }
        }

        Ok(PetLiteBatchEnergyVjpF32 {
            bar_input_node_embeddings: bar_node_embeddings,
            bar_input_edge_embeddings: bar_edge_embeddings,
            bar_edge_vectors,
            bar_edge_distances,
            bar_cutoff_factors,
            postprocessed_per_system: tail_vjp.postprocessed_per_system,
        })
    }

    pub fn forces_for_non_pbc_batch(
        &self,
        batch: &PetLiteBatch,
    ) -> Result<Vec<Vec3>, PetLiteError> {
        Ok(self
            .forces_and_displacement_gradient_for_batch(batch, false)?
            .0)
    }

    pub fn forces_and_displacement_gradient_for_batch(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
    ) -> Result<(Vec<Vec3>, Mat3), PetLiteError> {
        let (forces, displacement_gradient, _) = self
            .forces_displacement_gradient_and_energy_for_batch(
                batch,
                compute_displacement_gradient,
            )?;
        Ok((forces, displacement_gradient))
    }

    fn forces_displacement_gradient_and_energy_for_batch(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        self.forces_displacement_gradient_and_energy_for_batch_profiled(
            batch,
            compute_displacement_gradient,
            None,
        )
    }

    fn forces_displacement_gradient_and_energy_for_batch_profiled(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
        profile: Option<&mut PetLiteProfile>,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        let mut workspace = PetLiteForceWorkspace::default();
        self.forces_displacement_gradient_and_energy_for_batch_with_workspace_profiled(
            batch,
            compute_displacement_gradient,
            &mut workspace,
            profile,
        )
    }

    fn forces_displacement_gradient_and_energy_for_batch_with_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
        workspace: &mut PetLiteForceWorkspace,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        let runtime_dims = self.supported_runtime_dims()?;
        let cutoff_width = runtime_dims.cutoff_width;
        let edge_slots = batch
            .n_atoms
            .checked_mul(batch.max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET force edge slot count overflows"))?;
        if batch.edge_sources.len() != edge_slots || batch.edge_destinations.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET force batch edge source/destination lengths must be {edge_slots}, got {}/{}",
                batch.edge_sources.len(),
                batch.edge_destinations.len()
            )));
        }
        if batch.edge_raw_indices.len() != edge_slots || batch.edge_pair_cutoffs.len() != edge_slots
        {
            return Err(invalid_model(format!(
                "PET force batch raw-index/pair-cutoff lengths must be {edge_slots}, got {}/{}",
                batch.edge_raw_indices.len(),
                batch.edge_pair_cutoffs.len()
            )));
        }
        let raw_edges = batch.raw_edge_sources.len();
        if raw_edges == 0 {
            return Err(invalid_model("PET force batch raw edge list is empty"));
        }
        if batch.raw_edge_destinations.len() != raw_edges
            || batch.raw_edge_distances.len() != raw_edges
        {
            return Err(invalid_model(format!(
                "PET force batch raw destination/distance lengths must be {raw_edges}, got {}/{}",
                batch.raw_edge_destinations.len(),
                batch.raw_edge_distances.len()
            )));
        }
        expect_shape_len(
            "PET force raw_edge_vectors",
            &batch.raw_edge_vectors,
            raw_edges,
            3,
        )?;
        expect_shape_len(
            "PET force raw_edge_distances",
            &batch.raw_edge_distances,
            raw_edges,
            1,
        )?;
        expect_shape_len("PET force edge_vectors", &batch.edge_vectors, edge_slots, 3)?;
        expect_shape_len(
            "PET force edge_distances",
            &batch.edge_distances,
            edge_slots,
            1,
        )?;
        if batch.padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET force padding_mask length must be {edge_slots}, got {}",
                batch.padding_mask.len()
            )));
        }
        expect_shape_len(
            "PET force cutoff_factors",
            &batch.cutoff_factors,
            edge_slots,
            1,
        )?;

        let stage_start = Instant::now();
        let vjp = self.postprocessed_energy_vjp_for_batch_profiled(
            &batch.element_indices_nodes,
            &batch.element_indices_neighbors,
            &batch.reverse_neighbor_index,
            &batch.system_indices,
            &batch.edge_vectors,
            &batch.edge_distances,
            &batch.padding_mask,
            &batch.cutoff_factors,
            &[1.0],
            1,
            Some(&mut *workspace),
            profile.as_deref_mut(),
        )?;
        if let Some(profile) = &mut profile {
            profile.force.energy_vjp_total.record(stage_start);
        }
        let PetLiteBatchEnergyVjp {
            bar_edge_vectors,
            bar_edge_distances,
            bar_cutoff_factors,
            postprocessed_per_system,
            ..
        } = vjp;
        workspace.populate_profiled(
            raw_edges,
            batch.n_atoms,
            edge_slots,
            &batch.padding_mask,
            profile.as_deref_mut(),
        )?;
        let PetLiteForceWorkspace {
            raw_bar_vectors,
            bar_raw_distances,
            bar_atomic_cutoffs,
            adaptive_cutoff_vjp_scratch,
            active_edge_rows,
            active_edge_rows_are_sparse,
            touched_raw_edges,
            raw_edge_is_touched,
            touched_atomic_cutoff_nodes,
            atomic_cutoff_is_touched,
            ..
        } = workspace;
        let stage_start = Instant::now();
        let mut accumulate_edge_slot_vjp = |flat_slot: usize| -> Result<(), PetLiteError> {
            let raw_edge = batch.edge_raw_indices[flat_slot];
            if raw_edge >= raw_edges {
                return Err(invalid_model(format!(
                    "PET force active flat slot {flat_slot} raw edge index {raw_edge} is out of bounds for {raw_edges}"
                )));
            }
            let vector_start = flat_slot * 3;
            let vector = [
                batch.edge_vectors[vector_start],
                batch.edge_vectors[vector_start + 1],
                batch.edge_vectors[vector_start + 2],
            ];
            let mut bar_r = [
                bar_edge_vectors[vector_start],
                bar_edge_vectors[vector_start + 1],
                bar_edge_vectors[vector_start + 2],
            ];
            pet_edge_distance_for_batch_vjp_accumulate(
                &vector,
                bar_edge_distances[flat_slot],
                &mut bar_r,
            )?;
            let raw_vector_start = raw_edge * 3;
            for axis in 0..3 {
                raw_bar_vectors[raw_vector_start + axis] += bar_r[axis];
            }
            mark_pet_force_raw_edge_touched(touched_raw_edges, raw_edge_is_touched, raw_edge);

            let bar_cutoff_factor = bar_cutoff_factors[flat_slot];
            if bar_cutoff_factor != 0.0 {
                let pair_cutoff = batch.edge_pair_cutoffs[flat_slot];
                let (bar_distance, bar_pair_cutoff) = pet_bump_cutoff_vjp(
                    batch.raw_edge_distances[raw_edge],
                    pair_cutoff,
                    cutoff_width,
                    bar_cutoff_factor,
                )?;
                bar_raw_distances[raw_edge] += bar_distance;
                let bar_atomic_cutoff = 0.5 * bar_pair_cutoff;
                if bar_atomic_cutoff != 0.0 {
                    let source = batch.edge_sources[flat_slot];
                    let destination = batch.edge_destinations[flat_slot];
                    bar_atomic_cutoffs[source] += bar_atomic_cutoff;
                    mark_pet_force_atomic_cutoff_touched(
                        touched_atomic_cutoff_nodes,
                        atomic_cutoff_is_touched,
                        source,
                    );
                    bar_atomic_cutoffs[destination] += bar_atomic_cutoff;
                    mark_pet_force_atomic_cutoff_touched(
                        touched_atomic_cutoff_nodes,
                        atomic_cutoff_is_touched,
                        destination,
                    );
                }
            }
            Ok(())
        };
        if *active_edge_rows_are_sparse {
            for &flat_slot in active_edge_rows.iter() {
                accumulate_edge_slot_vjp(flat_slot)?;
            }
        } else {
            for flat_slot in 0..edge_slots {
                accumulate_edge_slot_vjp(flat_slot)?;
            }
        }
        if let Some(profile) = &mut profile {
            profile.force.padded_edge_geometry_vjp.record(stage_start);
        }

        let stage_start = Instant::now();
        if touched_atomic_cutoff_nodes
            .iter()
            .any(|&node| bar_atomic_cutoffs[node] != 0.0)
        {
            let (stats, _) = prepare_f64_scratch_len(
                &mut adaptive_cutoff_vjp_scratch.edge_bar_distances,
                raw_edges,
            );
            if let Some(profile) = &mut profile {
                profile
                    .allocations
                    .force_adaptive_bar_raw_distances
                    .record(stats);
            }
            pet_adaptive_atomic_cutoffs_vjp_visit_edge_bars(
                &batch.raw_edge_sources,
                &batch.raw_edge_distances,
                batch.n_atoms,
                self.max_neighbors() as f64,
                self.cutoff(),
                cutoff_width,
                bar_atomic_cutoffs,
                adaptive_cutoff_vjp_scratch,
                |raw_edge, bar_distance| {
                    if raw_edge >= raw_edges {
                        return Err(invalid_model(format!(
                            "PET adaptive cutoff VJP raw edge {raw_edge} is out of bounds for {raw_edges}"
                        )));
                    }
                    if bar_distance != 0.0 {
                        bar_raw_distances[raw_edge] += bar_distance;
                        mark_pet_force_raw_edge_touched(
                            touched_raw_edges,
                            raw_edge_is_touched,
                            raw_edge,
                        );
                    }
                    Ok(())
                },
            )?;
        }
        if let Some(profile) = &mut profile {
            profile.force.adaptive_cutoff_vjp.record(stage_start);
        }

        let mut forces = vec![[0.0; 3]; batch.n_atoms];
        let mut displacement_gradient = [[0.0; 3]; 3];
        let stage_start = Instant::now();
        for &raw_edge in touched_raw_edges.iter() {
            let vector_start = raw_edge * 3;
            let bar_raw_distance = bar_raw_distances[raw_edge];
            if bar_raw_distance == 0.0
                && raw_bar_vectors[vector_start] == 0.0
                && raw_bar_vectors[vector_start + 1] == 0.0
                && raw_bar_vectors[vector_start + 2] == 0.0
            {
                continue;
            }
            let vector = [
                batch.raw_edge_vectors[vector_start],
                batch.raw_edge_vectors[vector_start + 1],
                batch.raw_edge_vectors[vector_start + 2],
            ];
            let mut bar_r = [
                raw_bar_vectors[vector_start],
                raw_bar_vectors[vector_start + 1],
                raw_bar_vectors[vector_start + 2],
            ];
            pet_edge_distance_for_cutoff_vjp_accumulate(&vector, bar_raw_distance, &mut bar_r)?;
            scatter_edge_vector_vjp(
                batch.raw_edge_sources[raw_edge],
                batch.raw_edge_destinations[raw_edge],
                bar_r,
                &mut forces,
            )
            .map_err(|err| invalid_model(format!("PET force scatter failed: {err}")))?;
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(vector, bar_r, &mut displacement_gradient);
            }
        }
        if let Some(profile) = &mut profile {
            profile.force.force_scatter.record(stage_start);
        }
        workspace.vjp_bar_edge_vectors = bar_edge_vectors;
        workspace.vjp_bar_edge_distances = bar_edge_distances;
        Ok((forces, displacement_gradient, postprocessed_per_system))
    }

