    fn forces_displacement_gradient_and_energy_for_batch_f32(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        let mut workspace = PetLitePreparedBatchF32Workspace::new();
        self.forces_displacement_gradient_and_energy_for_batch_f32_with_workspace(
            batch,
            compute_displacement_gradient,
            &mut workspace,
            None,
        )
    }

    fn forces_displacement_gradient_and_energy_for_batch_f32_with_workspace(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
        workspace: &mut PetLitePreparedBatchF32Workspace,
        profile: Option<&mut PetLiteProfile>,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        self.forces_displacement_gradient_and_energy_for_batch_f32_with_workspace_profiled(
            batch,
            compute_displacement_gradient,
            workspace,
            profile,
        )
    }

    fn forces_displacement_gradient_and_energy_for_batch_f32_with_workspace_profiled(
        &self,
        batch: &PetLiteBatch,
        compute_displacement_gradient: bool,
        workspace: &mut PetLitePreparedBatchF32Workspace,
        mut profile: Option<&mut PetLiteProfile>,
    ) -> Result<(Vec<Vec3>, Mat3, Vec<f64>), PetLiteError> {
        let runtime_dims = self.supported_runtime_dims()?;
        if !self.has_native_f32_state_tensors() {
            return Err(PetLiteError::UnsupportedComputeDtype(
                PredictionComputeDtype::Float32,
            ));
        }
        let cutoff_width = runtime_dims.cutoff_width as f32;
        let edge_slots = batch
            .n_atoms
            .checked_mul(batch.max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 force edge slot count overflows"))?;
        if batch.edge_sources.len() != edge_slots || batch.edge_destinations.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET f32 force batch edge source/destination lengths must be {edge_slots}, got {}/{}",
                batch.edge_sources.len(),
                batch.edge_destinations.len()
            )));
        }
        if batch.edge_raw_indices.len() != edge_slots || batch.edge_pair_cutoffs.len() != edge_slots
        {
            return Err(invalid_model(format!(
                "PET f32 force batch raw-index/pair-cutoff lengths must be {edge_slots}, got {}/{}",
                batch.edge_raw_indices.len(),
                batch.edge_pair_cutoffs.len()
            )));
        }
        let raw_edges = batch.raw_edge_sources.len();
        if raw_edges == 0 {
            return Err(invalid_model("PET f32 force batch raw edge list is empty"));
        }
        if batch.raw_edge_destinations.len() != raw_edges
            || batch.raw_edge_distances.len() != raw_edges
        {
            return Err(invalid_model(format!(
                "PET f32 force batch raw destination/distance lengths must be {raw_edges}, got {}/{}",
                batch.raw_edge_destinations.len(),
                batch.raw_edge_distances.len()
            )));
        }
        expect_shape_len(
            "PET f32 force raw_edge_vectors",
            &batch.raw_edge_vectors,
            raw_edges,
            3,
        )?;
        expect_shape_len(
            "PET f32 force raw_edge_distances",
            &batch.raw_edge_distances,
            raw_edges,
            1,
        )?;
        expect_shape_len(
            "PET f32 force edge_vectors",
            &batch.edge_vectors,
            edge_slots,
            3,
        )?;
        expect_shape_len(
            "PET f32 force edge_distances",
            &batch.edge_distances,
            edge_slots,
            1,
        )?;
        if batch.padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET f32 force padding_mask length must be {edge_slots}, got {}",
                batch.padding_mask.len()
            )));
        }
        expect_shape_len(
            "PET f32 force cutoff_factors",
            &batch.cutoff_factors,
            edge_slots,
            1,
        )?;
        workspace.populate_from_batch_profiled(batch, profile.as_deref_mut());

        let stage_start = Instant::now();
        let vjp = self.postprocessed_energy_vjp_for_batch_f32_profiled(
            &batch.element_indices_nodes,
            &batch.element_indices_neighbors,
            &batch.reverse_neighbor_index,
            &batch.system_indices,
            &workspace.edge_vectors,
            &workspace.edge_distances,
            &batch.padding_mask,
            &workspace.cutoff_factors,
            &[1.0],
            1,
            Some(&mut workspace.force),
            profile.as_deref_mut(),
        )?;
        if let Some(profile) = &mut profile {
            profile.force.energy_vjp_total.record(stage_start);
        }
        let PetLiteBatchEnergyVjpF32 {
            bar_edge_vectors,
            bar_edge_distances,
            bar_cutoff_factors,
            postprocessed_per_system,
            ..
        } = vjp;
        workspace.force.populate_profiled(
            raw_edges,
            batch.n_atoms,
            edge_slots,
            &batch.padding_mask,
            profile.as_deref_mut(),
        )?;
        let PetLiteForceWorkspace {
            raw_bar_vectors,
            bar_raw_distances,
            bar_atomic_cutoffs,
            adaptive_cutoff_vjp_scratch_f32,
            active_edge_rows,
            active_edge_rows_are_sparse,
            touched_raw_edges,
            raw_edge_is_touched,
            touched_atomic_cutoff_nodes,
            atomic_cutoff_is_touched,
            ..
        } = &mut workspace.force;
        let stage_start = Instant::now();
        let mut accumulate_edge_slot_vjp = |flat_slot: usize| -> Result<(), PetLiteError> {
            let raw_edge = batch.edge_raw_indices[flat_slot];
            if raw_edge >= raw_edges {
                return Err(invalid_model(format!(
                    "PET f32 force active flat slot {flat_slot} raw edge index {raw_edge} is out of bounds for {raw_edges}"
                )));
            }
            let vector_start = flat_slot * 3;
            let vector = [
                workspace.edge_vectors[vector_start],
                workspace.edge_vectors[vector_start + 1],
                workspace.edge_vectors[vector_start + 2],
            ];
            let mut bar_r = [
                bar_edge_vectors[vector_start],
                bar_edge_vectors[vector_start + 1],
                bar_edge_vectors[vector_start + 2],
            ];
            pet_edge_distance_for_batch_vjp_accumulate_f32(
                &vector,
                bar_edge_distances[flat_slot],
                &mut bar_r,
            )?;
            let raw_vector_start = raw_edge * 3;
            for axis in 0..3 {
                raw_bar_vectors[raw_vector_start + axis] += bar_r[axis] as f64;
            }
            mark_pet_force_raw_edge_touched(touched_raw_edges, raw_edge_is_touched, raw_edge);

            let bar_cutoff_factor = bar_cutoff_factors[flat_slot];
            if bar_cutoff_factor != 0.0 {
                let pair_cutoff = batch.edge_pair_cutoffs[flat_slot] as f32;
                let (bar_distance, bar_pair_cutoff) = pet_bump_cutoff_vjp_f32(
                    batch.raw_edge_distances[raw_edge] as f32,
                    pair_cutoff,
                    cutoff_width,
                    bar_cutoff_factor,
                )?;
                bar_raw_distances[raw_edge] += bar_distance as f64;
                let bar_atomic_cutoff = 0.5 * bar_pair_cutoff as f64;
                if bar_atomic_cutoff != 0.0 {
                    let source = batch.edge_sources[flat_slot];
                    let destination = batch.edge_destinations[flat_slot];
                    bar_atomic_cutoffs[source] += bar_atomic_cutoff;
                    mark_pet_force_atomic_cutoff_touched(
                        touched_atomic_cutoff_nodes,
                        atomic_cutoff_is_touched,
                        source,
                    );
                    bar_atomic_cutoffs[destination] += bar_atomic_cutoff;
                    mark_pet_force_atomic_cutoff_touched(
                        touched_atomic_cutoff_nodes,
                        atomic_cutoff_is_touched,
                        destination,
                    );
                }
            }
            Ok(())
        };
        if *active_edge_rows_are_sparse {
            for &flat_slot in active_edge_rows.iter() {
                accumulate_edge_slot_vjp(flat_slot)?;
            }
        } else {
            for flat_slot in 0..edge_slots {
                accumulate_edge_slot_vjp(flat_slot)?;
            }
        }
        if let Some(profile) = &mut profile {
            profile.force.padded_edge_geometry_vjp.record(stage_start);
        }

        let stage_start = Instant::now();
        if touched_atomic_cutoff_nodes
            .iter()
            .any(|&node| bar_atomic_cutoffs[node] != 0.0)
        {
            let (stats, _) = prepare_f32_scratch_len(
                &mut adaptive_cutoff_vjp_scratch_f32.edge_bar_distances,
                raw_edges,
            );
            if let Some(profile) = &mut profile {
                profile
                    .allocations
                    .force_adaptive_bar_raw_distances
                    .record(stats);
            }
            pet_adaptive_atomic_cutoffs_vjp_visit_edge_bars_f32(
                &batch.raw_edge_sources,
                &batch.raw_edge_distances,
                batch.n_atoms,
                self.max_neighbors() as f32,
                self.cutoff() as f32,
                runtime_dims.cutoff_width as f32,
                bar_atomic_cutoffs,
                adaptive_cutoff_vjp_scratch_f32,
                |raw_edge, bar_distance| {
                    if raw_edge >= raw_edges {
                        return Err(invalid_model(format!(
                            "PET f32 adaptive cutoff VJP raw edge {raw_edge} is out of bounds for {raw_edges}"
                        )));
                    }
                    if bar_distance != 0.0 {
                        bar_raw_distances[raw_edge] += bar_distance as f64;
                        mark_pet_force_raw_edge_touched(
                            touched_raw_edges,
                            raw_edge_is_touched,
                            raw_edge,
                        );
                    }
                    Ok(())
                },
            )?;
        }
        if let Some(profile) = &mut profile {
            profile.force.adaptive_cutoff_vjp.record(stage_start);
        }

        let mut forces = vec![[0.0; 3]; batch.n_atoms];
        let mut displacement_gradient = [[0.0; 3]; 3];
        let stage_start = Instant::now();
        for &raw_edge in touched_raw_edges.iter() {
            let vector_start = raw_edge * 3;
            let bar_raw_distance = bar_raw_distances[raw_edge];
            if bar_raw_distance == 0.0
                && raw_bar_vectors[vector_start] == 0.0
                && raw_bar_vectors[vector_start + 1] == 0.0
                && raw_bar_vectors[vector_start + 2] == 0.0
            {
                continue;
            }
            let vector = [
                batch.raw_edge_vectors[vector_start],
                batch.raw_edge_vectors[vector_start + 1],
                batch.raw_edge_vectors[vector_start + 2],
            ];
            let mut bar_r = [
                raw_bar_vectors[vector_start],
                raw_bar_vectors[vector_start + 1],
                raw_bar_vectors[vector_start + 2],
            ];
            pet_edge_distance_for_cutoff_vjp_accumulate(&vector, bar_raw_distance, &mut bar_r)?;
            scatter_edge_vector_vjp(
                batch.raw_edge_sources[raw_edge],
                batch.raw_edge_destinations[raw_edge],
                bar_r,
                &mut forces,
            )
            .map_err(|err| invalid_model(format!("PET f32 force scatter failed: {err}")))?;
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(vector, bar_r, &mut displacement_gradient);
            }
        }
        if let Some(profile) = &mut profile {
            profile.force.force_scatter.record(stage_start);
        }
        workspace.force.vjp_bar_edge_vectors_f32 = bar_edge_vectors;
        workspace.force.vjp_bar_edge_distances_f32 = bar_edge_distances;
        Ok((forces, displacement_gradient, postprocessed_per_system))
    }

    pub fn energy_and_forces_for_non_pbc_structure(
        &self,
        structure: &Structure,
    ) -> Result<(f64, Vec<Vec3>), PetLiteError> {
        let batch = self.batch_for_non_pbc_structure(structure)?;
        let unscaled = self.unscaled_energy_for_batch(
            &batch.element_indices_nodes,
            &batch.element_indices_neighbors,
            &batch.reverse_neighbor_index,
            &batch.system_indices,
            &batch.edge_vectors,
            &batch.edge_distances,
            &batch.padding_mask,
            &batch.cutoff_factors,
            1,
        )?;
        let postprocessed = self.apply_energy_postprocessing(
            &batch.element_indices_nodes,
            &batch.system_indices,
            &unscaled.per_atom,
            1,
        )?;
        let energy = *postprocessed
            .per_system
            .first()
            .ok_or_else(|| invalid_model("PET post-processed energy output is empty"))?;
        let forces = self.forces_for_non_pbc_batch(&batch)?;
        Ok((energy, forces))
    }

    pub fn apply_energy_postprocessing(
        &self,
        element_indices_nodes: &[usize],
        system_indices: &[usize],
        unscaled_per_atom: &[f64],
        num_systems: usize,
    ) -> Result<PetLitePostprocessedEnergy, PetLiteError> {
        let postprocessing = self
            .energy_postprocessing
            .as_ref()
            .ok_or_else(|| invalid_model("PET energy post-processing metadata is not available"))?;
        if element_indices_nodes.len() != unscaled_per_atom.len() {
            return Err(invalid_model(format!(
                "PET energy post-processing requires {} element indices for {} per-atom predictions",
                unscaled_per_atom.len(),
                element_indices_nodes.len()
            )));
        }
        if system_indices.len() != unscaled_per_atom.len() {
            return Err(invalid_model(format!(
                "PET energy post-processing requires {} system indices for {} per-atom predictions",
                unscaled_per_atom.len(),
                system_indices.len()
            )));
        }

        let mut per_atom = Vec::with_capacity(unscaled_per_atom.len());
        for (atom, (&element_index, &unscaled)) in element_indices_nodes
            .iter()
            .zip(unscaled_per_atom)
            .enumerate()
        {
            if !unscaled.is_finite() {
                return Err(invalid_model(format!(
                    "PET unscaled per-atom energy atom {atom} must be finite"
                )));
            }
            let atomic_number = self
                .species
                .atomic_numbers
                .get(element_index)
                .ok_or_else(|| {
                    invalid_model(format!(
                        "element_indices_nodes[{atom}]={element_index} is out of bounds for {} PET species",
                        self.species.atomic_numbers.len()
                    ))
                })?;
            let composition_index = postprocessing
                .composition_additive
                .atomic_numbers
                .iter()
                .position(|number| number == atomic_number)
                .ok_or_else(|| {
                    invalid_model(format!(
                        "PET energy composition is missing atomic number {atomic_number}"
                    ))
                })?;
            per_atom.push(
                unscaled * postprocessing.scale.value
                    + postprocessing.composition_additive.values[composition_index],
            );
        }
        let per_system =
            Self::sum_per_atom_predictions_by_system(&per_atom, system_indices, num_systems, 1)?;
        Ok(PetLitePostprocessedEnergy {
            per_atom,
            per_system,
        })
    }

    pub fn combine_atomic_predictions(
        node_atomic_predictions: &[f64],
        edge_atomic_predictions: &[f64],
    ) -> Result<Vec<f64>, PetLiteError> {
        if node_atomic_predictions.len() != edge_atomic_predictions.len() {
            return Err(invalid_model(format!(
                "PET node atomic prediction length {} must match edge atomic prediction length {}",
                node_atomic_predictions.len(),
                edge_atomic_predictions.len()
            )));
        }
        node_atomic_predictions
            .iter()
            .zip(edge_atomic_predictions)
            .enumerate()
            .map(|(index, (node, edge))| {
                if !node.is_finite() || !edge.is_finite() {
                    return Err(invalid_model(format!(
                        "PET atomic prediction values at flat index {index} must be finite"
                    )));
                }
                Ok(node + edge)
            })
            .collect()
    }

    pub fn sum_per_atom_predictions_by_system(
        per_atom_predictions: &[f64],
        system_indices: &[usize],
        num_systems: usize,
        output_dim: usize,
    ) -> Result<Vec<f64>, PetLiteError> {
        if output_dim == 0 {
            return Err(invalid_model(
                "PET per-atom prediction output dimension must be nonzero",
            ));
        }
        if system_indices.len().checked_mul(output_dim) != Some(per_atom_predictions.len()) {
            return Err(invalid_model(format!(
                "PET per-atom prediction length {} must equal system_indices length {} times output_dim {output_dim}",
                per_atom_predictions.len(),
                system_indices.len()
            )));
        }
        let output_len = num_systems
            .checked_mul(output_dim)
            .ok_or_else(|| invalid_model("PET per-system prediction length overflows"))?;
        let mut per_system = vec![0.0; output_len];
        for (atom, &system_index) in system_indices.iter().enumerate() {
            if system_index >= num_systems {
                return Err(invalid_model(format!(
                    "system_indices[{atom}]={system_index} is out of bounds for {num_systems} systems"
                )));
            }
            let atom_start = atom
                .checked_mul(output_dim)
                .ok_or_else(|| invalid_model("PET per-atom prediction offset overflows"))?;
            let system_start = system_index
                .checked_mul(output_dim)
                .ok_or_else(|| invalid_model("PET per-system prediction offset overflows"))?;
            for component in 0..output_dim {
                let value = per_atom_predictions[atom_start + component];
                if !value.is_finite() {
                    return Err(invalid_model(format!(
                        "PET per-atom prediction atom {atom} component {component} must be finite"
                    )));
                }
                per_system[system_start + component] += value;
            }
        }
        Ok(per_system)
    }

    fn reduce_edge_predictions_by_slot(
        edge_predictions_by_slot: &[f64],
        cutoff_factors: &[f64],
        padding_mask: &[bool],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<Vec<f64>, PetLiteError> {
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET edge prediction slot count overflows"))?;
        expect_shape_len(
            "PET edge predictions by slot",
            edge_predictions_by_slot,
            edge_slots,
            1,
        )?;
        expect_shape_len("PET edge prediction cutoffs", cutoff_factors, edge_slots, 1)?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET edge prediction padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        let mut edge_atomic_predictions = vec![0.0; n_atoms];
        for (atom, edge_atomic_prediction) in edge_atomic_predictions.iter_mut().enumerate() {
            for edge in 0..max_edges_per_atom {
                let edge_slot = atom * max_edges_per_atom + edge;
                if padding_mask[edge_slot] {
                    *edge_atomic_prediction +=
                        edge_predictions_by_slot[edge_slot] * cutoff_factors[edge_slot];
                }
            }
        }
        Ok(edge_atomic_predictions)
    }

    fn reduce_active_edge_predictions(
        active_rows: &[usize],
        compact_edge_predictions: &[f64],
        cutoff_factors: &[f64],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<Vec<f64>, PetLiteError> {
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET active edge prediction slot count overflows"))?;
        expect_selected_rows("PET active edge prediction rows", active_rows, edge_slots)?;
        expect_shape_len(
            "PET active edge predictions",
            compact_edge_predictions,
            active_rows.len(),
            1,
        )?;
        expect_shape_len(
            "PET active edge prediction cutoffs",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        let mut edge_atomic_predictions = vec![0.0; n_atoms];
        for (&edge_slot, &prediction) in active_rows.iter().zip(compact_edge_predictions) {
            let atom = edge_slot / max_edges_per_atom;
            edge_atomic_predictions[atom] += prediction * cutoff_factors[edge_slot];
        }
        Ok(edge_atomic_predictions)
    }

    fn active_edge_prediction_vjp(
        active_rows: &[usize],
        compact_edge_predictions: &[f64],
        cutoff_factors: &[f64],
        bar_edge_atomic_predictions: &[f64],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<(Vec<f64>, Vec<f64>), PetLiteError> {
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET active edge prediction VJP slot count overflows"))?;
        expect_selected_rows(
            "PET active edge prediction VJP rows",
            active_rows,
            edge_slots,
        )?;
        expect_shape_len(
            "PET active edge prediction VJP compact predictions",
            compact_edge_predictions,
            active_rows.len(),
            1,
        )?;
        expect_shape_len(
            "PET active edge prediction VJP cutoffs",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        expect_shape_len(
            "PET active edge prediction VJP atomic bars",
            bar_edge_atomic_predictions,
            n_atoms,
            1,
        )?;
        let mut compact_bar_edge_predictions = vec![0.0; active_rows.len()];
        let mut bar_cutoff_factors = vec![0.0; edge_slots];
        for (compact_index, (&edge_slot, &prediction)) in
            active_rows.iter().zip(compact_edge_predictions).enumerate()
        {
            let atom = edge_slot / max_edges_per_atom;
            let bar_value = bar_edge_atomic_predictions[atom];
            compact_bar_edge_predictions[compact_index] += bar_value * cutoff_factors[edge_slot];
            bar_cutoff_factors[edge_slot] += bar_value * prediction;
        }
        Ok((compact_bar_edge_predictions, bar_cutoff_factors))
    }

    fn combine_atomic_predictions_f32_to_f64(
        node_atomic_predictions: &[f32],
        edge_atomic_predictions: &[f32],
    ) -> Result<Vec<f64>, PetLiteError> {
        if node_atomic_predictions.len() != edge_atomic_predictions.len() {
            return Err(invalid_model(format!(
                "PET f32 node atomic prediction length {} must match edge atomic prediction length {}",
                node_atomic_predictions.len(),
                edge_atomic_predictions.len()
            )));
        }
        node_atomic_predictions
            .iter()
            .zip(edge_atomic_predictions)
            .enumerate()
            .map(|(index, (node, edge))| {
                if !node.is_finite() || !edge.is_finite() {
                    return Err(invalid_model(format!(
                        "PET f32 atomic prediction values at flat index {index} must be finite"
                    )));
                }
                Ok(f64::from(*node) + f64::from(*edge))
            })
            .collect()
    }

    fn reduce_edge_predictions_by_slot_f32(
        edge_predictions_by_slot: &[f32],
        cutoff_factors: &[f32],
        padding_mask: &[bool],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<Vec<f32>, PetLiteError> {
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 edge prediction slot count overflows"))?;
        expect_shape_len_f32(
            "PET f32 edge predictions by slot",
            edge_predictions_by_slot,
            edge_slots,
            1,
        )?;
        expect_shape_len_f32(
            "PET f32 edge prediction cutoffs",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        if padding_mask.len() != edge_slots {
            return Err(invalid_model(format!(
                "PET f32 edge prediction padding_mask length must be {edge_slots}, got {}",
                padding_mask.len()
            )));
        }
        let mut edge_atomic_predictions = vec![0.0; n_atoms];
        for (atom, edge_atomic_prediction) in edge_atomic_predictions.iter_mut().enumerate() {
            for edge in 0..max_edges_per_atom {
                let edge_slot = atom * max_edges_per_atom + edge;
                if padding_mask[edge_slot] {
                    *edge_atomic_prediction +=
                        edge_predictions_by_slot[edge_slot] * cutoff_factors[edge_slot];
                }
            }
        }
        Ok(edge_atomic_predictions)
    }

    fn reduce_active_edge_predictions_f32(
        active_rows: &[usize],
        compact_edge_predictions: &[f32],
        cutoff_factors: &[f32],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<Vec<f32>, PetLiteError> {
        let edge_slots = n_atoms
            .checked_mul(max_edges_per_atom)
            .ok_or_else(|| invalid_model("PET f32 active edge prediction slot count overflows"))?;
        expect_selected_rows(
            "PET f32 active edge prediction rows",
            active_rows,
            edge_slots,
        )?;
        expect_shape_len_f32(
            "PET f32 active edge predictions",
            compact_edge_predictions,
            active_rows.len(),
            1,
        )?;
        expect_shape_len_f32(
            "PET f32 active edge prediction cutoffs",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        let mut edge_atomic_predictions = vec![0.0; n_atoms];
        for (&edge_slot, &prediction) in active_rows.iter().zip(compact_edge_predictions) {
            let atom = edge_slot / max_edges_per_atom;
            edge_atomic_predictions[atom] += prediction * cutoff_factors[edge_slot];
        }
        Ok(edge_atomic_predictions)
    }

    fn active_edge_prediction_vjp_f32(
        active_rows: &[usize],
        compact_edge_predictions: &[f32],
        cutoff_factors: &[f32],
        bar_edge_atomic_predictions: &[f32],
        n_atoms: usize,
        max_edges_per_atom: usize,
    ) -> Result<(Vec<f32>, Vec<f32>), PetLiteError> {
        let edge_slots = n_atoms.checked_mul(max_edges_per_atom).ok_or_else(|| {
            invalid_model("PET f32 active edge prediction VJP slot count overflows")
        })?;
        expect_selected_rows(
            "PET f32 active edge prediction VJP rows",
            active_rows,
            edge_slots,
        )?;
        expect_shape_len_f32(
            "PET f32 active edge prediction VJP compact predictions",
            compact_edge_predictions,
            active_rows.len(),
            1,
        )?;
        expect_shape_len_f32(
            "PET f32 active edge prediction VJP cutoffs",
            cutoff_factors,
            edge_slots,
            1,
        )?;
        expect_shape_len_f32(
            "PET f32 active edge prediction VJP atomic bars",
            bar_edge_atomic_predictions,
            n_atoms,
            1,
        )?;
        let mut compact_bar_edge_predictions = vec![0.0; active_rows.len()];
        let mut bar_cutoff_factors = vec![0.0; edge_slots];
        for (compact_index, (&edge_slot, &prediction)) in
            active_rows.iter().zip(compact_edge_predictions).enumerate()
        {
            let atom = edge_slot / max_edges_per_atom;
            let bar_value = bar_edge_atomic_predictions[atom];
            compact_bar_edge_predictions[compact_index] += bar_value * cutoff_factors[edge_slot];
            bar_cutoff_factors[edge_slot] += bar_value * prediction;
        }
        Ok((compact_bar_edge_predictions, bar_cutoff_factors))
    }

