#[allow(clippy::too_many_arguments, dead_code)]
fn attention_atom_forward_f32(
    projected_atom: &[f32],
    padding_mask: &[bool],
    cutoff_factors: &[f32],
    seq_len: usize,
    d_edge: usize,
    num_heads: usize,
    head_dim: usize,
    scale: f32,
    attention_atom: &mut [f32],
    mut probabilities_atom: Option<&mut [f32]>,
    active_tokens_only: bool,
    mut profile_detail: Option<&mut PetLiteAttentionCoreDetail>,
) -> Result<(), PetLiteError> {
    if !can_use_attention_stack_path(seq_len, d_edge, num_heads, head_dim) {
        return Err(PetLiteError::UnsupportedRuntime);
    }
    expect_shape_len_f32(
        "PET f32 attention projected atom",
        projected_atom,
        seq_len,
        3 * d_edge,
    )?;
    expect_shape_len_f32(
        "PET f32 attention atom output",
        attention_atom,
        seq_len,
        d_edge,
    )?;
    if padding_mask.len() != seq_len - 1 {
        return Err(invalid_model(format!(
            "PET f32 attention padding mask length must be {}, got {}",
            seq_len - 1,
            padding_mask.len()
        )));
    }
    expect_shape_len_f32(
        "PET f32 attention cutoff atom",
        cutoff_factors,
        seq_len - 1,
        1,
    )?;
    let active_tokens = attention_active_tokens_stack(seq_len, padding_mask, active_tokens_only);
    if let Some(probabilities) = probabilities_atom.as_deref() {
        let expected = if active_tokens_only {
            num_heads * active_tokens.len * active_tokens.len
        } else {
            num_heads * seq_len * seq_len
        };
        if probabilities.len() != expected {
            return Err(invalid_model(format!(
                "PET f32 attention probabilities length must be {expected}, got {}",
                probabilities.len()
            )));
        }
    }
    let key_factors = attention_atom_key_factors_stack_f32(padding_mask, cutoff_factors, seq_len);
    let qkv_token_stride = 3 * d_edge;
    for head in 0..num_heads {
        let head_offset = head * head_dim;
        let probability_head_start = if active_tokens_only {
            head * active_tokens.len * active_tokens.len
        } else {
            head * seq_len * seq_len
        };
        for (query_index, &query) in active_tokens.as_slice().iter().enumerate() {
            let q_base = query * qkv_token_stride + head_offset;
            let score_start = pet_attention_detail_start(&profile_detail);
            let mut scores = [0.0_f32; PET_ATTENTION_STACK_SEQ_CAPACITY];
            let mut max_score = f32::NEG_INFINITY;
            for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                let mut dot = 0.0;
                for dim in 0..head_dim {
                    dot += projected_atom[q_base + dim] * projected_atom[k_base + dim];
                }
                let score = dot * scale + key_factors[key];
                scores[key_index] = score;
                max_score = max_score.max(score);
            }
            record_pet_attention_score_detail(&mut profile_detail, score_start);
            let softmax_start = pet_attention_detail_start(&profile_detail);
            let mut denom = 0.0;
            for score in &mut scores[..active_tokens.len] {
                *score = (*score - max_score).exp();
                denom += *score;
            }
            if !denom.is_finite() || denom <= 0.0 {
                return Err(invalid_model("PET f32 attention softmax is invalid"));
            }
            for score in &mut scores[..active_tokens.len] {
                *score /= denom;
            }
            if let Some(probabilities) = probabilities_atom.as_deref_mut() {
                let probability_row_start = if active_tokens_only {
                    probability_head_start + query_index * active_tokens.len
                } else {
                    probability_head_start + query * seq_len
                };
                if active_tokens_only {
                    probabilities[probability_row_start..probability_row_start + active_tokens.len]
                        .copy_from_slice(&scores[..active_tokens.len]);
                } else {
                    for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                        probabilities[probability_row_start + key] = scores[key_index];
                    }
                }
            }
            record_pet_attention_softmax_detail(&mut profile_detail, softmax_start);

            let value_start = pet_attention_detail_start(&profile_detail);
            let mut value = [0.0_f32; PET_ATTENTION_STACK_HEAD_DIM_CAPACITY];
            for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                let probability = scores[key_index];
                let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                for dim in 0..head_dim {
                    value[dim] += probability * projected_atom[v_base + dim];
                }
            }
            let output_start = query * d_edge + head_offset;
            attention_atom[output_start..output_start + head_dim]
                .copy_from_slice(&value[..head_dim]);
            record_pet_attention_value_detail(&mut profile_detail, value_start);
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn attention_atom_vjp(
    projected_atom: &[f64],
    bar_attention_atom: &[f64],
    padding_mask: &[bool],
    cutoff_factors: &[f64],
    seq_len: usize,
    d_edge: usize,
    num_heads: usize,
    head_dim: usize,
    scale: f64,
    bar_projected_atom: &mut [f64],
    bar_cutoff_atom: &mut [f64],
    active_tokens_only: bool,
) -> Result<(), PetLiteError> {
    if can_use_attention_stack_path(seq_len, d_edge, num_heads, head_dim) {
        let key_factors = attention_atom_key_factors_stack(padding_mask, cutoff_factors, seq_len);
        let active_tokens =
            attention_active_tokens_stack(seq_len, padding_mask, active_tokens_only);
        let qkv_token_stride = 3 * d_edge;
        for head in 0..num_heads {
            let head_offset = head * head_dim;
            for &query in active_tokens.as_slice() {
                let q_base = query * qkv_token_stride + head_offset;
                let mut scores = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
                let mut max_score = f64::NEG_INFINITY;
                for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                    let k_base = key * qkv_token_stride + d_edge + head_offset;
                    let mut dot = 0.0;
                    for dim in 0..head_dim {
                        dot += projected_atom[q_base + dim] * projected_atom[k_base + dim];
                    }
                    let score = dot * scale + key_factors[key];
                    scores[key_index] = score;
                    max_score = max_score.max(score);
                }
                let mut denom = 0.0;
                for score in &mut scores[..active_tokens.len] {
                    *score = (*score - max_score).exp();
                    denom += *score;
                }
                if !denom.is_finite() || denom <= 0.0 {
                    return Err(invalid_model("PET attention VJP softmax is invalid"));
                }
                let mut probabilities = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
                for key_index in 0..active_tokens.len {
                    probabilities[key_index] = scores[key_index] / denom;
                }

                let mut bar_probability = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
                for dim in 0..head_dim {
                    let bar_value = bar_attention_atom[query * d_edge + head_offset + dim];
                    for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                        let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                        bar_probability[key_index] += bar_value * projected_atom[v_base + dim];
                        bar_projected_atom[v_base + dim] += bar_value * probabilities[key_index];
                    }
                }

                let probability_bar_dot = (0..active_tokens.len)
                    .map(|key_index| probabilities[key_index] * bar_probability[key_index])
                    .sum::<f64>();
                for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                    let bar_score = probabilities[key_index]
                        * (bar_probability[key_index] - probability_bar_dot);
                    let k_base = key * qkv_token_stride + d_edge + head_offset;
                    for dim in 0..head_dim {
                        bar_projected_atom[q_base + dim] +=
                            bar_score * scale * projected_atom[k_base + dim];
                        bar_projected_atom[k_base + dim] +=
                            bar_score * scale * projected_atom[q_base + dim];
                    }
                    if key > 0 {
                        let edge = key - 1;
                        if padding_mask[edge] && cutoff_factors[edge] > PET_MAD_XS_ATTENTION_EPS {
                            bar_cutoff_atom[edge] += bar_score / cutoff_factors[edge];
                        }
                    }
                }
            }
        }
        return Ok(());
    }

    let key_factors = attention_atom_key_factors(padding_mask, cutoff_factors, seq_len);
    let key_factors = key_factors.as_slice();
    let qkv_token_stride = 3 * d_edge;
    let mut scores = AttentionScratch::new(seq_len);
    let mut probabilities = AttentionScratch::new(seq_len);
    let mut bar_probability = AttentionScratch::new(seq_len);
    for head in 0..num_heads {
        let head_offset = head * head_dim;
        for query in 0..seq_len {
            let q_base = query * qkv_token_stride + head_offset;
            bar_probability.fill(0.0);
            let scores = scores.as_mut_slice();
            let mut max_score = f64::NEG_INFINITY;
            for key in 0..seq_len {
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                let mut dot = 0.0;
                for dim in 0..head_dim {
                    dot += projected_atom[q_base + dim] * projected_atom[k_base + dim];
                }
                let score = dot * scale + key_factors[key];
                scores[key] = score;
                max_score = max_score.max(score);
            }
            let mut denom = 0.0;
            for score in &mut scores[..seq_len] {
                *score = (*score - max_score).exp();
                denom += *score;
            }
            if !denom.is_finite() || denom <= 0.0 {
                return Err(invalid_model("PET attention VJP softmax is invalid"));
            }
            let probabilities = probabilities.as_mut_slice();
            for key in 0..seq_len {
                probabilities[key] = scores[key] / denom;
            }

            let bar_probability = bar_probability.as_mut_slice();
            for dim in 0..head_dim {
                let bar_value = bar_attention_atom[query * d_edge + head_offset + dim];
                for key in 0..seq_len {
                    let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                    bar_probability[key] += bar_value * projected_atom[v_base + dim];
                    bar_projected_atom[v_base + dim] += bar_value * probabilities[key];
                }
            }

            let probability_bar_dot = (0..seq_len)
                .map(|key| probabilities[key] * bar_probability[key])
                .sum::<f64>();
            for key in 0..seq_len {
                let bar_score = probabilities[key] * (bar_probability[key] - probability_bar_dot);
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                for dim in 0..head_dim {
                    bar_projected_atom[q_base + dim] +=
                        bar_score * scale * projected_atom[k_base + dim];
                    bar_projected_atom[k_base + dim] +=
                        bar_score * scale * projected_atom[q_base + dim];
                }
                if key > 0 {
                    let edge = key - 1;
                    if padding_mask[edge] && cutoff_factors[edge] > PET_MAD_XS_ATTENTION_EPS {
                        bar_cutoff_atom[edge] += bar_score / cutoff_factors[edge];
                    }
                }
            }
        }
    }
    Ok(())
}

