#[allow(clippy::too_many_arguments)]
fn attention_atom_vjp_from_probabilities(
    projected_atom: &[f64],
    probabilities_atom: &[f64],
    bar_attention_atom: &[f64],
    padding_mask: &[bool],
    cutoff_factors: &[f64],
    seq_len: usize,
    d_edge: usize,
    num_heads: usize,
    head_dim: usize,
    scale: f64,
    bar_projected_atom: &mut [f64],
    bar_cutoff_atom: &mut [f64],
    active_tokens_only: bool,
    mut profile_detail: Option<&mut PetLiteAttentionCoreDetail>,
) -> Result<(), PetLiteError> {
    let expected_probabilities = num_heads * seq_len * seq_len;
    if probabilities_atom.len() != expected_probabilities {
        return Err(invalid_model(format!(
            "PET attention probability cache length must be {}, got {}",
            expected_probabilities,
            probabilities_atom.len()
        )));
    }
    if can_use_attention_stack_path(seq_len, d_edge, num_heads, head_dim) {
        let active_tokens =
            attention_active_tokens_stack(seq_len, padding_mask, active_tokens_only);
        for head in 0..num_heads {
            let head_offset = head * head_dim;
            let qkv_token_stride = 3 * d_edge;
            for &query in active_tokens.as_slice() {
                let probability_start = attention_probability_local_index(seq_len, head, query, 0);
                let probabilities =
                    &probabilities_atom[probability_start..probability_start + seq_len];
                let q_base = query * qkv_token_stride + head_offset;
                let mut bar_probability = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
                let value_detail_start = pet_attention_detail_start(&profile_detail);
                for dim in 0..head_dim {
                    let bar_value = bar_attention_atom[query * d_edge + head_offset + dim];
                    for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                        let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                        bar_probability[key_index] += bar_value * projected_atom[v_base + dim];
                        bar_projected_atom[v_base + dim] += bar_value * probabilities[key];
                    }
                }
                record_pet_attention_value_detail(&mut profile_detail, value_detail_start);

                let mut bar_scores = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
                let softmax_detail_start = pet_attention_detail_start(&profile_detail);
                let probability_bar_dot = active_tokens
                    .as_slice()
                    .iter()
                    .enumerate()
                    .map(|(key_index, &key)| probabilities[key] * bar_probability[key_index])
                    .sum::<f64>();
                for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                    bar_scores[key_index] =
                        probabilities[key] * (bar_probability[key_index] - probability_bar_dot);
                }
                record_pet_attention_softmax_detail(&mut profile_detail, softmax_detail_start);

                let score_detail_start = pet_attention_detail_start(&profile_detail);
                for (key_index, &key) in active_tokens.as_slice().iter().enumerate() {
                    let bar_score = bar_scores[key_index];
                    let k_base = key * qkv_token_stride + d_edge + head_offset;
                    for dim in 0..head_dim {
                        bar_projected_atom[q_base + dim] +=
                            bar_score * scale * projected_atom[k_base + dim];
                        bar_projected_atom[k_base + dim] +=
                            bar_score * scale * projected_atom[q_base + dim];
                    }
                    if key > 0 {
                        let edge = key - 1;
                        if padding_mask[edge] && cutoff_factors[edge] > PET_MAD_XS_ATTENTION_EPS {
                            bar_cutoff_atom[edge] += bar_score / cutoff_factors[edge];
                        }
                    }
                }
                record_pet_attention_score_detail(&mut profile_detail, score_detail_start);
            }
        }
        return Ok(());
    }

    let mut bar_probability = AttentionScratch::new(seq_len);
    let mut bar_scores = AttentionScratch::new(seq_len);
    let qkv_token_stride = 3 * d_edge;
    for head in 0..num_heads {
        let head_offset = head * head_dim;
        for query in 0..seq_len {
            let probability_start = attention_probability_local_index(seq_len, head, query, 0);
            let probabilities = &probabilities_atom[probability_start..probability_start + seq_len];
            let q_base = query * qkv_token_stride + head_offset;
            bar_probability.fill(0.0);
            let bar_probability = bar_probability.as_mut_slice();
            let value_detail_start = pet_attention_detail_start(&profile_detail);
            for dim in 0..head_dim {
                let bar_value = bar_attention_atom[query * d_edge + head_offset + dim];
                for key in 0..seq_len {
                    let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                    bar_probability[key] += bar_value * projected_atom[v_base + dim];
                    bar_projected_atom[v_base + dim] += bar_value * probabilities[key];
                }
            }
            record_pet_attention_value_detail(&mut profile_detail, value_detail_start);

            bar_scores.fill(0.0);
            let bar_scores = bar_scores.as_mut_slice();
            let softmax_detail_start = pet_attention_detail_start(&profile_detail);
            let probability_bar_dot = (0..seq_len)
                .map(|key| probabilities[key] * bar_probability[key])
                .sum::<f64>();
            for key in 0..seq_len {
                bar_scores[key] = probabilities[key] * (bar_probability[key] - probability_bar_dot);
            }
            record_pet_attention_softmax_detail(&mut profile_detail, softmax_detail_start);

            let score_detail_start = pet_attention_detail_start(&profile_detail);
            for (key, &bar_score) in bar_scores.iter().enumerate().take(seq_len) {
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                for dim in 0..head_dim {
                    bar_projected_atom[q_base + dim] +=
                        bar_score * scale * projected_atom[k_base + dim];
                    bar_projected_atom[k_base + dim] +=
                        bar_score * scale * projected_atom[q_base + dim];
                }
                if key > 0 {
                    let edge = key - 1;
                    if padding_mask[edge] && cutoff_factors[edge] > PET_MAD_XS_ATTENTION_EPS {
                        bar_cutoff_atom[edge] += bar_score / cutoff_factors[edge];
                    }
                }
            }
            record_pet_attention_score_detail(&mut profile_detail, score_detail_start);
        }
    }
    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn attention_atom_vjp_compact_bar_projected(
    projected_atom: &[f64],
    active_tokens: &[usize],
    bar_attention_atom: &[f64],
    padding_mask: &[bool],
    cutoff_factors: &[f64],
    seq_len: usize,
    d_edge: usize,
    num_heads: usize,
    head_dim: usize,
    scale: f64,
    compact_bar_projected_atom: &mut [f64],
    bar_cutoff_atom: &mut [f64],
) -> Result<(), PetLiteError> {
    if active_tokens.is_empty() || active_tokens.len() > PET_ATTENTION_STACK_SEQ_CAPACITY {
        return Err(invalid_model(
            "PET compact attention VJP active token count is invalid",
        ));
    }
    let active_len = active_tokens.len();
    let qkv_token_stride = 3 * d_edge;
    let expected_projected = seq_len * qkv_token_stride;
    if projected_atom.len() != expected_projected {
        return Err(invalid_model(format!(
            "compact attention VJP projected atom length must be {expected_projected}, got {}",
            projected_atom.len()
        )));
    }
    let expected_bar_attention = active_len * d_edge;
    if bar_attention_atom.len() != expected_bar_attention {
        return Err(invalid_model(format!(
            "compact attention VJP bar_attention_atom length must be {expected_bar_attention}, got {}",
            bar_attention_atom.len()
        )));
    }
    let expected_bar_projected = active_len * qkv_token_stride;
    if compact_bar_projected_atom.len() != expected_bar_projected {
        return Err(invalid_model(format!(
            "compact attention VJP bar_projected atom length must be {expected_bar_projected}, got {}",
            compact_bar_projected_atom.len()
        )));
    }
    let key_factors = attention_atom_key_factors_stack(padding_mask, cutoff_factors, seq_len);
    for head in 0..num_heads {
        let head_offset = head * head_dim;
        for (query_index, &query) in active_tokens.iter().enumerate() {
            let q_base = query * qkv_token_stride + head_offset;
            let q_compact_base = query_index * qkv_token_stride + head_offset;
            let mut scores = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
            let mut max_score = f64::NEG_INFINITY;
            for (key_index, &key) in active_tokens.iter().enumerate() {
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                let mut dot = 0.0;
                for dim in 0..head_dim {
                    dot += projected_atom[q_base + dim] * projected_atom[k_base + dim];
                }
                let score = dot * scale + key_factors[key];
                scores[key_index] = score;
                max_score = max_score.max(score);
            }
            let mut denom = 0.0;
            for score in &mut scores[..active_tokens.len()] {
                *score = (*score - max_score).exp();
                denom += *score;
            }
            if !denom.is_finite() || denom <= 0.0 {
                return Err(invalid_model(
                    "PET compact attention VJP softmax is invalid",
                ));
            }
            let mut probabilities = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
            for key_index in 0..active_tokens.len() {
                probabilities[key_index] = scores[key_index] / denom;
            }

            let mut bar_probability = [0.0_f64; PET_ATTENTION_STACK_SEQ_CAPACITY];
            let bar_value_base = query_index * d_edge + head_offset;
            for (key_index, &key) in active_tokens.iter().enumerate() {
                let probability = probabilities[key_index];
                let v_base = key * qkv_token_stride + 2 * d_edge + head_offset;
                let v_compact_base = key_index * qkv_token_stride + 2 * d_edge + head_offset;
                let mut dot = 0.0;
                for dim in 0..head_dim {
                    let bar_value = bar_attention_atom[bar_value_base + dim];
                    dot += bar_value * projected_atom[v_base + dim];
                    compact_bar_projected_atom[v_compact_base + dim] += bar_value * probability;
                }
                bar_probability[key_index] = dot;
            }

            let probability_bar_dot = (0..active_tokens.len())
                .map(|key_index| probabilities[key_index] * bar_probability[key_index])
                .sum::<f64>();
            for (key_index, &key) in active_tokens.iter().enumerate() {
                let bar_score =
                    probabilities[key_index] * (bar_probability[key_index] - probability_bar_dot);
                let k_base = key * qkv_token_stride + d_edge + head_offset;
                let k_compact_base = key_index * qkv_token_stride + d_edge + head_offset;
                for dim in 0..head_dim {
                    compact_bar_projected_atom[q_compact_base + dim] +=
                        bar_score * scale * projected_atom[k_base + dim];
                    compact_bar_projected_atom[k_compact_base + dim] +=
                        bar_score * scale * projected_atom[q_base + dim];
                }
                if key > 0 {
                    let edge = key - 1;
                    if padding_mask[edge] && cutoff_factors[edge] > PET_MAD_XS_ATTENTION_EPS {
                        bar_cutoff_atom[edge] += bar_score / cutoff_factors[edge];
                    }
                }
            }
        }
    }
    Ok(())
}

