fn compose_dense_vjp_prefix_weight(
    first_weight: &[f64],
    first_out_dim: usize,
    first_full_in_dim: usize,
    first_selected_in_dim: usize,
    second_weight: &[f64],
    second_in_dim: usize,
) -> Result<Vec<f64>, PetLiteError> {
    if first_selected_in_dim > first_full_in_dim {
        return Err(invalid_model(format!(
            "dense VJP weight composition selected dimension {first_selected_in_dim} exceeds full dimension {first_full_in_dim}"
        )));
    }
    expect_shape_len(
        "dense VJP composition first weight",
        first_weight,
        first_out_dim,
        first_full_in_dim,
    )?;
    expect_shape_len(
        "dense VJP composition second weight",
        second_weight,
        first_selected_in_dim,
        second_in_dim,
    )?;
    let mut composed = vec![0.0; first_out_dim * second_in_dim];
    for first_out in 0..first_out_dim {
        let first_row = &first_weight
            [first_out * first_full_in_dim..first_out * first_full_in_dim + first_selected_in_dim];
        for selected in 0..first_selected_in_dim {
            let first_value = first_row[selected];
            let second_row =
                &second_weight[selected * second_in_dim..(selected + 1) * second_in_dim];
            for second_in in 0..second_in_dim {
                composed[first_out * second_in_dim + second_in] +=
                    first_value * second_row[second_in];
            }
        }
    }
    Ok(composed)
}

