#[allow(clippy::too_many_arguments)]
fn compose_dense_forward_prefix_weight_and_bias(
    first_weight: &[f64],
    first_bias: &[f64],
    first_out_dim: usize,
    first_in_dim: usize,
    second_weight: &[f64],
    second_out_dim: usize,
    second_full_in_dim: usize,
    second_selected_in_dim: usize,
    second_bias: &[f64],
) -> Result<(Vec<f64>, Vec<f64>), PetLiteError> {
    if second_selected_in_dim > second_full_in_dim {
        return Err(invalid_model(format!(
            "dense forward weight composition selected dimension {second_selected_in_dim} exceeds full dimension {second_full_in_dim}"
        )));
    }
    expect_shape_len(
        "dense forward composition first weight",
        first_weight,
        first_out_dim,
        first_in_dim,
    )?;
    if first_bias.len() != first_out_dim {
        return Err(invalid_model(format!(
            "dense forward composition first bias length must be {first_out_dim}, got {}",
            first_bias.len()
        )));
    }
    expect_shape_len(
        "dense forward composition second weight",
        second_weight,
        second_out_dim,
        second_full_in_dim,
    )?;
    if second_selected_in_dim != first_out_dim {
        return Err(invalid_model(format!(
            "dense forward composition selected dimension {second_selected_in_dim} must match first output dimension {first_out_dim}"
        )));
    }
    if second_bias.len() != second_out_dim {
        return Err(invalid_model(format!(
            "dense forward composition second bias length must be {second_out_dim}, got {}",
            second_bias.len()
        )));
    }
    let mut composed_weight = vec![0.0; second_out_dim * first_in_dim];
    let mut composed_bias = second_bias.to_vec();
    for second_out in 0..second_out_dim {
        let second_row = &second_weight[second_out * second_full_in_dim
            ..second_out * second_full_in_dim + second_selected_in_dim];
        for first_out in 0..second_selected_in_dim {
            let second_value = second_row[first_out];
            composed_bias[second_out] += second_value * first_bias[first_out];
            let first_row = &first_weight[first_out * first_in_dim..(first_out + 1) * first_in_dim];
            for first_in in 0..first_in_dim {
                composed_weight[second_out * first_in_dim + first_in] +=
                    second_value * first_row[first_in];
            }
        }
    }
    Ok((composed_weight, composed_bias))
}

