fn rms_norm_rows(
    values: &mut [f64],
    rows: usize,
    width: usize,
    weight: &[f64],
) -> Result<(), PetLiteError> {
    expect_shape_len("RMSNorm values", values, rows, width)?;
    expect_shape_len("RMSNorm weight", weight, 1, width)?;
    for row in 0..rows {
        let start = row * width;
        let end = start + width;
        let mean_square = values[start..end]
            .iter()
            .map(|value| value * value)
            .sum::<f64>()
            / width as f64;
        let scale = 1.0 / (mean_square + f64::EPSILON).sqrt();
        for column in 0..width {
            values[start + column] *= scale * weight[column];
        }
    }
    Ok(())
}

fn rms_norm_rows_cached_inv_rms(
    values: &mut [f64],
    rows: usize,
    width: usize,
    weight: &[f64],
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len("RMSNorm values", values, rows, width)?;
    expect_shape_len("RMSNorm weight", weight, 1, width)?;
    let mut inv_rms = vec![0.0; rows];
    #[cfg(feature = "parallel")]
    let mut used_parallel_rows = false;
    #[cfg(not(feature = "parallel"))]
    let used_parallel_rows = false;
    #[cfg(feature = "parallel")]
    if should_parallel_row_values(rows, width) {
        values
            .par_chunks_mut(width)
            .zip(inv_rms.par_iter_mut())
            .for_each(|(row_values, inv_rms_value)| {
                let mean_square =
                    row_values.iter().map(|value| value * value).sum::<f64>() / width as f64;
                let scale = 1.0 / (mean_square + f64::EPSILON).sqrt();
                *inv_rms_value = scale;
                for column in 0..width {
                    row_values[column] *= scale * weight[column];
                }
            });
        used_parallel_rows = true;
    }
    if !used_parallel_rows {
        for (row, inv_rms_value) in inv_rms.iter_mut().enumerate() {
            let start = row * width;
            let end = start + width;
            let mean_square = values[start..end]
                .iter()
                .map(|value| value * value)
                .sum::<f64>()
                / width as f64;
            let scale = 1.0 / (mean_square + f64::EPSILON).sqrt();
            *inv_rms_value = scale;
            for column in 0..width {
                values[start + column] *= scale * weight[column];
            }
        }
    }
    Ok(inv_rms)
}

