fn rms_norm_rows_input_vjp_from_inv_rms(
    input: &[f64],
    rows: usize,
    width: usize,
    weight: &[f64],
    inv_rms: &[f64],
    bar_output: &[f64],
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len("RMSNorm cached VJP input", input, rows, width)?;
    expect_shape_len("RMSNorm cached VJP weight", weight, 1, width)?;
    expect_shape_len("RMSNorm cached VJP bar_output", bar_output, rows, width)?;
    if inv_rms.len() != rows {
        return Err(invalid_model(format!(
            "RMSNorm cached VJP inv_rms length must be {rows}, got {}",
            inv_rms.len()
        )));
    }
    let mut bar_input = vec![0.0; rows * width];
    #[cfg(feature = "parallel")]
    let mut used_parallel_rows = false;
    #[cfg(not(feature = "parallel"))]
    let used_parallel_rows = false;
    #[cfg(feature = "parallel")]
    if should_parallel_row_values(rows, width) {
        bar_input
            .par_chunks_mut(width)
            .zip(input.par_chunks(width))
            .zip(bar_output.par_chunks(width))
            .zip(inv_rms.par_iter())
            .for_each(|(((bar_input_row, input_row), bar_output_row), &scale)| {
                let scale_cubed = scale * scale * scale;
                let coupling = (0..width)
                    .map(|column| bar_output_row[column] * weight[column] * input_row[column])
                    .sum::<f64>();
                let correction_scale = scale_cubed * coupling / width as f64;
                for column in 0..width {
                    bar_input_row[column] = bar_output_row[column] * weight[column] * scale
                        - input_row[column] * correction_scale;
                }
            });
        used_parallel_rows = true;
    }
    if !used_parallel_rows {
        for (row, &scale) in inv_rms.iter().enumerate() {
            let start = row * width;
            let scale_cubed = scale * scale * scale;
            let coupling = (0..width)
                .map(|column| bar_output[start + column] * weight[column] * input[start + column])
                .sum::<f64>();
            for column in 0..width {
                let input_value = input[start + column];
                bar_input[start + column] = bar_output[start + column] * weight[column] * scale
                    - input_value * scale_cubed * coupling / width as f64;
            }
        }
    }
    Ok(bar_input)
}

#[allow(clippy::too_many_arguments)]
fn rms_norm_rows_input_vjp_from_inv_rms_selected(
    input: &[f64],
    rows: usize,
    width: usize,
    weight: &[f64],
    inv_rms: &[f64],
    selected_rows: &[usize],
    bar_output: &[f64],
    label: &str,
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len(label, input, rows, width)?;
    expect_shape_len("RMSNorm selected cached VJP weight", weight, 1, width)?;
    expect_selected_rows("RMSNorm selected cached VJP rows", selected_rows, rows)?;
    expect_shape_len(
        "RMSNorm selected cached VJP bar_output",
        bar_output,
        selected_rows.len(),
        width,
    )?;
    if inv_rms.len() != rows {
        return Err(invalid_model(format!(
            "RMSNorm selected cached VJP inv_rms length must be {rows}, got {}",
            inv_rms.len()
        )));
    }
    #[cfg(feature = "parallel")]
    if should_parallel_row_values(selected_rows.len(), width) {
        let mut bar_input = vec![0.0; selected_rows.len() * width];
        bar_input
            .par_chunks_mut(width)
            .zip(selected_rows.par_iter())
            .zip(bar_output.par_chunks(width))
            .for_each(|((bar_input_row, &row), bar_output_row)| {
                let input_start = row * width;
                let input_row = &input[input_start..input_start + width];
                let scale = inv_rms[row];
                let scale_cubed = scale * scale * scale;
                let coupling = bar_output_row
                    .iter()
                    .zip(weight)
                    .zip(input_row)
                    .map(|((bar_value, weight_value), input_value)| {
                        bar_value * weight_value * input_value
                    })
                    .sum::<f64>();
                let correction_scale = scale_cubed * coupling / width as f64;
                for column in 0..width {
                    let input_value = input_row[column];
                    bar_input_row[column] = bar_output_row[column] * weight[column] * scale
                        - input_value * correction_scale;
                }
            });
        return Ok(bar_input);
    }
    let mut bar_input = Vec::with_capacity(selected_rows.len() * width);
    for (compact_row, &row) in selected_rows.iter().enumerate() {
        let input_start = row * width;
        let output_start = compact_row * width;
        let scale = inv_rms[row];
        let scale_cubed = scale * scale * scale;
        let coupling = (0..width)
            .map(|column| {
                bar_output[output_start + column] * weight[column] * input[input_start + column]
            })
            .sum::<f64>();
        let correction_scale = scale_cubed * coupling / width as f64;
        for column in 0..width {
            let input_value = input[input_start + column];
            bar_input.push(
                bar_output[output_start + column] * weight[column] * scale
                    - input_value * correction_scale,
            );
        }
    }
    Ok(bar_input)
}

