#[allow(dead_code)]
fn layer_norm_rows_input_vjp(
    input: &[f64],
    rows: usize,
    width: usize,
    weight: &[f64],
    bar_output: &[f64],
    eps: f64,
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len("LayerNorm VJP input", input, rows, width)?;
    expect_shape_len("LayerNorm VJP weight", weight, 1, width)?;
    expect_shape_len("LayerNorm VJP bar_output", bar_output, rows, width)?;
    if !eps.is_finite() || eps <= 0.0 {
        return Err(invalid_model(
            "LayerNorm VJP eps must be positive and finite",
        ));
    }
    let mut bar_input = vec![0.0; rows * width];
    for row in 0..rows {
        let start = row * width;
        let end = start + width;
        let mean = input[start..end].iter().sum::<f64>() / width as f64;
        let variance = input[start..end]
            .iter()
            .map(|value| {
                let centered = value - mean;
                centered * centered
            })
            .sum::<f64>()
            / width as f64;
        let inv_std = 1.0 / (variance + eps).sqrt();
        let mut sum_bar_normed = 0.0;
        let mut sum_bar_normed_times_xhat = 0.0;
        for column in 0..width {
            let centered = input[start + column] - mean;
            let xhat = centered * inv_std;
            let bar_normed = bar_output[start + column] * weight[column];
            sum_bar_normed += bar_normed;
            sum_bar_normed_times_xhat += bar_normed * xhat;
        }
        let mean_bar_normed = sum_bar_normed / width as f64;
        let mean_bar_normed_times_xhat = sum_bar_normed_times_xhat / width as f64;
        for column in 0..width {
            let centered = input[start + column] - mean;
            let xhat = centered * inv_std;
            let bar_normed = bar_output[start + column] * weight[column];
            bar_input[start + column] =
                inv_std * (bar_normed - mean_bar_normed - xhat * mean_bar_normed_times_xhat);
        }
    }
    Ok(bar_input)
}

