#[cfg(feature = "parallel")]
fn selected_rows_are_strictly_increasing(selected_rows: &[usize]) -> bool {
    selected_rows.windows(2).all(|window| window[0] < window[1])
}

fn scatter_selected_rows_to_padded(
    compact: &[f64],
    rows: usize,
    dim: usize,
    selected_rows: &[usize],
    label: &str,
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len(label, compact, selected_rows.len(), dim)?;
    expect_selected_rows(label, selected_rows, rows)?;
    let mut padded = vec![0.0; rows * dim];
    #[cfg(feature = "parallel")]
    if should_parallel_row_values(selected_rows.len(), dim)
        && selected_rows_are_strictly_increasing(selected_rows)
    {
        let row_block = rows.div_ceil(rayon::current_num_threads().max(1)).max(1);
        padded
            .par_chunks_mut(row_block * dim)
            .enumerate()
            .for_each(|(block, padded_block)| {
                let row_start = block * row_block;
                let block_rows = padded_block.len() / dim;
                let row_end = row_start + block_rows;
                let selected_start = selected_rows.partition_point(|&row| row < row_start);
                let selected_end = selected_start
                    + selected_rows[selected_start..].partition_point(|&row| row < row_end);
                for (offset, &row) in selected_rows[selected_start..selected_end]
                    .iter()
                    .enumerate()
                {
                    let compact_row = selected_start + offset;
                    let padded_start = (row - row_start) * dim;
                    let compact_start = compact_row * dim;
                    padded_block[padded_start..padded_start + dim]
                        .copy_from_slice(&compact[compact_start..compact_start + dim]);
                }
            });
        return Ok(padded);
    }
    for (compact_row, &row) in selected_rows.iter().enumerate() {
        padded[row * dim..(row + 1) * dim]
            .copy_from_slice(&compact[compact_row * dim..(compact_row + 1) * dim]);
    }
    Ok(padded)
}

