fn scatter_add_selected_rows(
    target: &mut [f64],
    rows: usize,
    dim: usize,
    selected_rows: &[usize],
    compact: &[f64],
    label: &str,
) -> Result<(), PetLiteError> {
    expect_shape_len(label, target, rows, dim)?;
    expect_shape_len(label, compact, selected_rows.len(), dim)?;
    expect_selected_rows(label, selected_rows, rows)?;
    #[cfg(feature = "parallel")]
    if should_parallel_row_values(selected_rows.len(), dim)
        && selected_rows_are_strictly_increasing(selected_rows)
    {
        let row_block = rows.div_ceil(rayon::current_num_threads().max(1)).max(1);
        target
            .par_chunks_mut(row_block * dim)
            .enumerate()
            .for_each(|(block, target_block)| {
                let row_start = block * row_block;
                let block_rows = target_block.len() / dim;
                let row_end = row_start + block_rows;
                let selected_start = selected_rows.partition_point(|&row| row < row_start);
                let selected_end = selected_start
                    + selected_rows[selected_start..].partition_point(|&row| row < row_end);
                for (offset, &row) in selected_rows[selected_start..selected_end]
                    .iter()
                    .enumerate()
                {
                    let compact_row_index = selected_start + offset;
                    let target_start = (row - row_start) * dim;
                    let compact_start = compact_row_index * dim;
                    let target_row = &mut target_block[target_start..target_start + dim];
                    let compact_row = &compact[compact_start..compact_start + dim];
                    for (target_value, compact_value) in target_row.iter_mut().zip(compact_row) {
                        *target_value += compact_value;
                    }
                }
            });
        return Ok(());
    }
    for (compact_row, &row) in selected_rows.iter().enumerate() {
        let target_row = &mut target[row * dim..(row + 1) * dim];
        let compact_row = &compact[compact_row * dim..(compact_row + 1) * dim];
        for (target_value, compact_value) in target_row.iter_mut().zip(compact_row) {
            *target_value += compact_value;
        }
    }
    Ok(())
}

