#[allow(clippy::too_many_arguments)]
fn swiglu_feed_forward_cached(
    input: &[f64],
    rows: usize,
    in_dim: usize,
    hidden_dim: usize,
    out_dim: usize,
    w_in: &[f64],
    b_in: &[f64],
    w_out: &[f64],
    b_out: &[f64],
) -> Result<PetLiteSwigluForwardCache, PetLiteError> {
    let mut value_gate_projection = dense_forward(input, rows, in_dim, w_in, b_in)?;
    expect_shape_len(
        "SwiGLU input projection",
        &value_gate_projection,
        rows,
        2 * hidden_dim,
    )?;
    let mut hidden = vec![0.0; rows * hidden_dim];
    #[cfg(feature = "parallel")]
    let mut used_parallel_swiglu = false;
    #[cfg(not(feature = "parallel"))]
    let used_parallel_swiglu = false;
    #[cfg(feature = "parallel")]
    if should_parallel_swiglu_rows(rows, hidden_dim) {
        hidden
            .par_chunks_mut(hidden_dim)
            .zip(value_gate_projection.par_chunks_mut(2 * hidden_dim))
            .enumerate()
            .for_each(|(_row, (hidden_row, projected_row))| {
                for column in 0..hidden_dim {
                    let value = projected_row[column];
                    let gate = projected_row[hidden_dim + column];
                    let sig = sigmoid(gate);
                    projected_row[hidden_dim + column] = sig;
                    hidden_row[column] = value * sig;
                }
            });
        used_parallel_swiglu = true;
    }
    if !used_parallel_swiglu {
        for row in 0..rows {
            let projected_start = row * 2 * hidden_dim;
            let hidden_start = row * hidden_dim;
            for column in 0..hidden_dim {
                let value = value_gate_projection[projected_start + column];
                let gate = value_gate_projection[projected_start + hidden_dim + column];
                let sig = sigmoid(gate);
                value_gate_projection[projected_start + hidden_dim + column] = sig;
                hidden[hidden_start + column] = value * sig;
            }
        }
    }
    if b_out.len() != out_dim {
        return Err(invalid_model(format!(
            "SwiGLU output bias length must be {out_dim}, got {}",
            b_out.len()
        )));
    }
    let output = dense_forward(&hidden, rows, hidden_dim, w_out, b_out)?;
    Ok(PetLiteSwigluForwardCache {
        output,
        value_gate_projection,
    })
}

