#[allow(clippy::too_many_arguments, dead_code)]
fn swiglu_feed_forward_input_vjp(
    input: &[f64],
    rows: usize,
    in_dim: usize,
    hidden_dim: usize,
    out_dim: usize,
    w_in: &[f64],
    b_in: &[f64],
    w_out: &[f64],
    b_out: &[f64],
    bar_output: &[f64],
) -> Result<Vec<f64>, PetLiteError> {
    let projected = dense_forward(input, rows, in_dim, w_in, b_in)?;
    swiglu_feed_forward_input_vjp_from_projected(
        &projected, None, rows, in_dim, hidden_dim, out_dim, w_in, w_out, b_out, bar_output,
    )
}

#[allow(clippy::too_many_arguments)]
fn swiglu_feed_forward_input_vjp_from_projected(
    projected: &[f64],
    gate_sigmoid: Option<&[f64]>,
    rows: usize,
    in_dim: usize,
    hidden_dim: usize,
    out_dim: usize,
    w_in: &[f64],
    w_out: &[f64],
    b_out: &[f64],
    bar_output: &[f64],
) -> Result<Vec<f64>, PetLiteError> {
    expect_shape_len(
        "SwiGLU cached input projection",
        projected,
        rows,
        2 * hidden_dim,
    )?;
    if let Some(gate_sigmoid) = gate_sigmoid {
        expect_shape_len("SwiGLU cached gate sigmoid", gate_sigmoid, rows, hidden_dim)?;
    }
    if b_out.len() != out_dim {
        return Err(invalid_model(format!(
            "SwiGLU VJP output bias length must be {out_dim}, got {}",
            b_out.len()
        )));
    }
    let bar_hidden = dense_input_vjp(bar_output, rows, hidden_dim, w_out, out_dim)?;
    let mut bar_projected = vec![0.0; rows * 2 * hidden_dim];
    #[cfg(feature = "parallel")]
    let mut used_parallel_swiglu = false;
    #[cfg(not(feature = "parallel"))]
    let used_parallel_swiglu = false;
    #[cfg(feature = "parallel")]
    if should_parallel_swiglu_rows(rows, hidden_dim) {
        if let Some(gate_sigmoid) = gate_sigmoid {
            bar_projected
                .par_chunks_mut(2 * hidden_dim)
                .zip(bar_hidden.par_chunks(hidden_dim))
                .zip(gate_sigmoid.par_chunks(hidden_dim))
                .enumerate()
                .for_each(
                    |(row, ((bar_projected_row, bar_hidden_row), sigmoid_row))| {
                        let projected_start = row * 2 * hidden_dim;
                        for column in 0..hidden_dim {
                            let value = projected[projected_start + column];
                            let sig = sigmoid_row[column];
                            let bar_value = bar_hidden_row[column];
                            bar_projected_row[column] += bar_value * sig;
                            bar_projected_row[hidden_dim + column] +=
                                bar_value * value * sig * (1.0 - sig);
                        }
                    },
                );
        } else {
            bar_projected
                .par_chunks_mut(2 * hidden_dim)
                .zip(bar_hidden.par_chunks(hidden_dim))
                .enumerate()
                .for_each(|(row, (bar_projected_row, bar_hidden_row))| {
                    let projected_start = row * 2 * hidden_dim;
                    for column in 0..hidden_dim {
                        let value = projected[projected_start + column];
                        let sig = sigmoid(projected[projected_start + hidden_dim + column]);
                        let bar_value = bar_hidden_row[column];
                        bar_projected_row[column] += bar_value * sig;
                        bar_projected_row[hidden_dim + column] +=
                            bar_value * value * sig * (1.0 - sig);
                    }
                });
        }
        used_parallel_swiglu = true;
    }
    if !used_parallel_swiglu {
        for row in 0..rows {
            let projected_start = row * 2 * hidden_dim;
            let hidden_start = row * hidden_dim;
            for column in 0..hidden_dim {
                let value = projected[projected_start + column];
                let sig = gate_sigmoid.map_or_else(
                    || sigmoid(projected[projected_start + hidden_dim + column]),
                    |sigmoid_values| sigmoid_values[hidden_start + column],
                );
                let bar_value = bar_hidden[hidden_start + column];
                bar_projected[projected_start + column] += bar_value * sig;
                bar_projected[projected_start + hidden_dim + column] +=
                    bar_value * value * sig * (1.0 - sig);
            }
        }
    }
    dense_input_vjp(&bar_projected, rows, in_dim, w_in, 2 * hidden_dim)
}

