    #[test]
    fn pet_geometry_cutoff_f32_helpers_match_f64_baseline() {
        let vector = [0.7, -1.2, 2.1];
        let vector_f32 = [vector[0] as f32, vector[1] as f32, vector[2] as f32];
        let cutoff_distance = pet_edge_distance_for_cutoff(&vector);
        let cutoff_distance_f32 = pet_edge_distance_for_cutoff_f32(&vector_f32);
        assert!(
            (cutoff_distance_f32 as f64 - cutoff_distance).abs() <= 2.0e-7,
            "f32 cutoff distance mismatch: actual {cutoff_distance_f32}, expected {cutoff_distance}"
        );
        let batch_distance = pet_edge_distance_for_batch(&vector);
        let batch_distance_f32 = pet_edge_distance_for_batch_f32(&vector_f32);
        assert!(
            (batch_distance_f32 as f64 - batch_distance).abs() <= 2.0e-7,
            "f32 batch distance mismatch: actual {batch_distance_f32}, expected {batch_distance}"
        );

        let mut expected_bar_cutoff = [0.3, -0.4, 0.5];
        let mut actual_bar_cutoff = [
            expected_bar_cutoff[0] as f32,
            expected_bar_cutoff[1] as f32,
            expected_bar_cutoff[2] as f32,
        ];
        pet_edge_distance_for_cutoff_vjp_accumulate(&vector, -0.8, &mut expected_bar_cutoff)
            .expect("f64 cutoff distance VJP succeeds");
        pet_edge_distance_for_cutoff_vjp_accumulate_f32(&vector_f32, -0.8, &mut actual_bar_cutoff)
            .expect("f32 cutoff distance VJP succeeds");
        assert_close_vec_f32_to_f64(
            &actual_bar_cutoff,
            &expected_bar_cutoff,
            2.0e-6,
            "f32 cutoff distance VJP",
        );

        let mut expected_bar_batch = [0.1, 0.2, -0.3];
        let mut actual_bar_batch = [
            expected_bar_batch[0] as f32,
            expected_bar_batch[1] as f32,
            expected_bar_batch[2] as f32,
        ];
        pet_edge_distance_for_batch_vjp_accumulate(&vector, 0.6, &mut expected_bar_batch)
            .expect("f64 batch distance VJP succeeds");
        pet_edge_distance_for_batch_vjp_accumulate_f32(&vector_f32, 0.6, &mut actual_bar_batch)
            .expect("f32 batch distance VJP succeeds");
        assert_close_vec_f32_to_f64(
            &actual_bar_batch,
            &expected_bar_batch,
            2.0e-6,
            "f32 batch distance VJP",
        );

        let distance = 7.82;
        let cutoff = 8.0;
        let width = 0.5;
        let expected_cutoff =
            pet_bump_cutoff(distance, cutoff, width).expect("f64 cutoff succeeds");
        let actual_cutoff = pet_bump_cutoff_f32(distance as f32, cutoff as f32, width as f32)
            .expect("f32 cutoff succeeds");
        assert!(
            (actual_cutoff as f64 - expected_cutoff).abs() <= 2.0e-6,
            "f32 bump cutoff mismatch: actual {actual_cutoff}, expected {expected_cutoff}"
        );

        let expected_cutoff_vjp =
            pet_bump_cutoff_vjp(distance, cutoff, width, -0.9).expect("f64 cutoff VJP succeeds");
        let actual_cutoff_vjp =
            pet_bump_cutoff_vjp_f32(distance as f32, cutoff as f32, width as f32, -0.9)
                .expect("f32 cutoff VJP succeeds");
        assert!(
            (actual_cutoff_vjp.0 as f64 - expected_cutoff_vjp.0).abs()
                <= 2.0e-5 * expected_cutoff_vjp.0.abs().max(1.0),
            "f32 bump cutoff distance VJP mismatch: actual {}, expected {}",
            actual_cutoff_vjp.0,
            expected_cutoff_vjp.0
        );
        assert!(
            (actual_cutoff_vjp.1 as f64 - expected_cutoff_vjp.1).abs()
                <= 2.0e-5 * expected_cutoff_vjp.1.abs().max(1.0),
            "f32 bump cutoff cutoff VJP mismatch: actual {}, expected {}",
            actual_cutoff_vjp.1,
            expected_cutoff_vjp.1
        );
    }

    #[test]
    fn pet_f32_bump_transition_probe_range_matches_partition_points() {
        let cutoff_width = 0.5_f32;
        let probe_spacing = cutoff_width / 4.0;
        let probe_start = 0.5_f32;
        let max_cutoff = 8.0_f32;
        let mut probe_cutoffs = Vec::new();
        let mut probe = probe_start;
        while probe < max_cutoff {
            probe_cutoffs.push(probe);
            probe += probe_spacing;
        }
        let mut distances = (0..512)
            .map(|index| index as f32 * 0.017)
            .collect::<Vec<_>>();
        for &cutoff in &probe_cutoffs {
            distances.push(cutoff);
            distances.push((cutoff - 1.0e-5).max(0.0));
            distances.push(cutoff + 1.0e-5);
            distances.push((cutoff - cutoff_width).max(0.0));
            distances.push((cutoff - cutoff_width - 1.0e-5).max(0.0));
            distances.push((cutoff - cutoff_width + 1.0e-5).max(0.0));
        }
        for distance in distances {
            let expected_start = probe_cutoffs.partition_point(|&cutoff| cutoff <= distance);
            let expected_end =
                probe_cutoffs.partition_point(|&cutoff| cutoff < distance + cutoff_width);
            let actual = bump_transition_probe_index_range_f32(
                distance,
                probe_start,
                probe_spacing,
                cutoff_width,
                probe_cutoffs.len(),
            );
            assert_eq!(
                actual,
                (expected_start, expected_end),
                "distance {distance}"
            );
        }
    }

